window.ANSWER_TERMS = {"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"lysosoom":{"title":"Lysosoom","short":"Membraanblaasje vol verterende enzymen dat afvalstoffen en opgenomen materiaal afbreekt.","definition":"<p>Het <b>lysosoom</b> is een blaasje omgeven door één membraan, gevuld met hydrolytische enzymen die bij een lage pH (~4,5) macromoleculen afbreken. Het is de 'maag' van de cel.</p><p>Het verteert materiaal dat via endocytose of fagocytose is opgenomen en ruimt via autofagie versleten celonderdelen op.</p>","image_url":"","wiki_title":"Lysosome","match":"lysosoom|lysosomen"},"peroxisoom":{"title":"Peroxisoom","short":"Klein organel dat vetzuren afbreekt en daarbij waterstofperoxide vormt, dat het met catalase onschadelijk maakt.","definition":"<p>Het <b>peroxisoom</b> is een klein, door één membraan omgeven organel. Het breekt lange vetzuren af (β-oxidatie) en ontgift stoffen, waarbij waterstofperoxide (H₂O₂) ontstaat.</p><p>Het enzym catalase in het peroxisoom zet dit reactieve H₂O₂ meteen om in water en zuurstof.</p>","image_url":"","wiki_title":"Peroxisome","match":"peroxisoom|peroxisomen"},"glad endoplasmatisch reticulum":{"title":"Glad endoplasmatisch reticulum","short":"ER zonder ribosomen; maakt lipiden, ontgift stoffen en slaat calcium op.","definition":"<p>Het <b>glad endoplasmatisch reticulum</b> heeft geen ribosomen. Het synthetiseert lipiden en steroïden, ontgift geneesmiddelen (vooral in de lever) en slaat Ca²⁺ op.</p><p>In spiercellen (sarcoplasmatisch reticulum) regelt de calciumopslag de spiercontractie.</p>","image_url":"","wiki_title":"Endoplasmic reticulum","match":"glad endoplasmatisch reticulum|glad ER"},"mitochondrion":{"title":"Mitochondrion","short":"De 'energiecentrale' van de cel; produceert ATP via de citroenzuurcyclus en oxidatieve fosforylering.","definition":"<p>Het <b>mitochondrion</b> heeft een dubbele membraan; de binnenste is sterk geplooid (cristae). Hier vinden de citroenzuurcyclus en de elektronentransportketen plaats.</p><p>Zo levert het mitochondrion het grootste deel van de ATP van de cel. Het bevat eigen DNA en kan zich delen.</p>","image_url":"","wiki_title":"Mitochondrion","match":"mitochondrion|mitochondriën|mitochondrien|mitochondria|mitochondrium"},"actine":{"title":"Actine","short":"Eiwit dat microfilamenten vormt; betrokken bij celvorm, celbeweging en spiercontractie.","definition":"<p><b>Actine</b> is een van de meest voorkomende eiwitten in de cel. Losse moleculen (G-actine) polymeriseren tot dunne draden (F-actine): de microfilamenten van het cytoskelet.</p><p>Actinefilamenten geven de cel vorm, maken beweging en deling mogelijk en vormen samen met myosine het contractiele apparaat van spiercellen.</p>","image_url":"","wiki_title":"Actin","match":"actine|actinefilamenten|actinefilament"},"myosine":{"title":"Myosine","short":"Motoreiwit dat langs actinefilamenten beweegt en zo spiercontractie en intracellulair transport aandrijft.","definition":"<p><b>Myosine</b> is een motoreiwit dat onder verbruik van ATP kracht levert door langs actinefilamenten te 'lopen'.</p><p>In spiercellen glijden myosine- en actinefilamenten langs elkaar, wat de spier doet samentrekken (het glijdende-filamentmodel).</p>","image_url":"","wiki_title":"Myosin","match":"myosine|myosinefilamenten|myosinefilament"},"desmosoom":{"title":"Desmosoom","short":"Sterke celverbinding (macula adherens) die naburige keratinocyten aan elkaar koppelt voor mechanische stevigheid.","definition":"<p>Een <b>desmosoom</b> is een knoopvormige adhesieverbinding die twee cellen stevig verbindt via cadherines (desmogleïne en desmocolline), verankerd aan het keratine-cytoskelet (tonofilamenten).</p><p>Desmosomen geven weefsel dat aan trekkracht blootstaat, zoals huid, zijn stevigheid. Bij pemphigus vulgaris worden ze door auto-antistoffen aangevallen.</p>","image_url":"","wiki_title":"Desmosome","match":"desmosoom|desmosomen"},"gap junctions":{"title":"Gap junction","short":"Kanaaltjes tussen aangrenzende cellen waardoor ionen en kleine moleculen rechtstreeks kunnen overgaan.","definition":"<p>Een <b>gap junction</b> is een kanaalverbinding (van connexinen) die het cytoplasma van twee cellen rechtstreeks verbindt.</p><p>Ionen en kleine moleculen stromen er direct doorheen, wat cellen elektrisch en metabool koppelt — belangrijk in hart- en gladde spier.</p>","image_url":"","wiki_title":"Gap junction","match":"gap junctions|gap junction"},"glycoproteine":{"title":"Glycoproteïne","short":"Eiwit met aangehechte suikerketens; veel membraan- en secretie-eiwitten zijn geglycosyleerd.","definition":"<p>Een <b>glycoproteïne</b> is een eiwit waaraan tijdens de rijping in ER en Golgi suikerketens zijn gekoppeld (glycosylering).</p><p>Ze zitten veel in de celmembraan en in secreten en spelen een rol bij herkenning, adhesie en bescherming.</p>","image_url":"","wiki_title":"Glycoprotein","match":"glycoproteïne|glycoproteine|glycoproteïnen|glycoproteinen|glycoproteinen"},"proteoglycaan":{"title":"Proteoglycaan","short":"Eiwit met lange glycosaminoglycaan-ketens; waterbindend hoofdbestanddeel van de extracellulaire matrix.","definition":"<p>Een <b>proteoglycaan</b> bestaat uit een kerneiwit met glycosaminoglycaan-ketens (zoals chondroïtinesulfaat). Door hun negatieve lading trekken ze veel water aan.</p><p>Ze vormen een gel-achtige grondsubstantie in bindweefsel en kraakbeen die druk opvangt en waarin vezels zijn ingebed.</p>","image_url":"","wiki_title":"Proteoglycan","match":"proteoglycaan|proteoglycanen"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"fagocytose":{"title":"Fagocytose","short":"Het 'opeten' van grote deeltjes of hele cellen (zoals bacteriën) door een cel via insluiting in een fagosoom.","definition":"<p><b>Fagocytose</b> is een vorm van endocytose waarbij een cel grote deeltjes omsluit, zoals bacteriën, celresten of stofdeeltjes.</p><p>Het gevormde fagosoom versmelt met een lysosoom, waarna de inhoud wordt verteerd. Neutrofielen en macrofagen zijn de belangrijkste fagocyten.</p>","image_url":"","wiki_title":"Phagocytosis","match":"fagocytose"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"glycolyse":{"title":"Glycolyse","short":"Afbraak van glucose tot pyruvaat in het cytoplasma, met een kleine netto-opbrengst aan ATP en NADH.","definition":"<p><b>Glycolyse</b> splitst in het cytoplasma één glucose in tien stappen tot twee moleculen pyruvaat.</p><p>Het levert netto 2 ATP en 2 NADH op en verloopt zonder zuurstof. Bij aanwezigheid van zuurstof gaat pyruvaat de citroenzuurcyclus in.</p>","image_url":"","wiki_title":"Glycolysis","match":"glycolyse"},"oxidatieve fosforylering":{"title":"Oxidatieve fosforylering","short":"Vorming van het grootste deel van de ATP via de elektronentransportketen en ATP-synthase in het mitochondrion.","definition":"<p>Bij <b>oxidatieve fosforylering</b> drijft de protongradiënt van de elektronentransportketen het enzym ATP-synthase aan.</p><p>Zo wordt uit ADP en fosfaat ATP gevormd — de belangrijkste ATP-bron van de cel, waarvoor zuurstof nodig is.</p>","image_url":"","wiki_title":"Oxidative phosphorylation","match":"oxidatieve fosforylering"},"fosforylering":{"title":"Fosforylering","short":"Toevoeging van een fosfaatgroep aan een eiwit; een veelgebruikte aan/uit-schakelaar van eiwitactiviteit.","definition":"<p><b>Fosforylering</b> is het koppelen van een fosfaatgroep aan een eiwit door een kinase. Een fosfatase haalt hem er weer af.</p><p>Zo schakelen cellen eiwitten razendsnel aan of uit — de basis van veel signaaltransductie.</p>","image_url":"","wiki_title":"Phosphorylation","match":"fosforylering|fosforylatie"},"epidermis":{"title":"Epidermis","short":"De opperhuid: het bovenste, uit meerlagig verhoornend plaveiselepitheel opgebouwde deel van de huid.","definition":"<p>De <b>epidermis</b> (opperhuid) is de buitenste huidlaag, opgebouwd uit meerlagig verhoornend plaveiselepitheel zonder bloedvaten.</p><p>Ze bestaat vooral uit keratinocyten in opeenvolgende lagen (basale → hoornlaag) en levert de beschermende barrière.</p>","image_url":"","wiki_title":"Epidermis","match":"epidermis|de epidermis"},"dermis":{"title":"Dermis","short":"De lederhuid onder de epidermis: bindweefsel met collageen, bloedvaten, zenuwen, klieren en haarfollikels.","definition":"<p>De <b>dermis</b> (lederhuid) ligt onder de epidermis en bestaat uit bindweefsel met collageen en elastine.</p><p>Ze bevat bloedvaten, zenuwuiteinden, zweet- en talgklieren en haarfollikels en geeft de huid stevigheid en elasticiteit. Men onderscheidt een papillaire en een reticulaire dermis.</p>","image_url":"","wiki_title":"Dermis","match":"dermis|de dermis|papillaire dermis|reticulaire dermis"},"fibroblast":{"title":"Fibroblast","short":"De belangrijkste bindweefselcel; produceert collageen, elastine en de overige extracellulaire matrix.","definition":"<p>De <b>fibroblast</b> is de meest voorkomende cel in bindweefsel en de dermis. Hij maakt de vezels (collageen, elastine) en de grondsubstantie aan.</p><p>Bij wondgenezing migreren fibroblasten naar de wond, vormen nieuw matrixmateriaal en kunnen als myofibroblast de wond samentrekken.</p>","image_url":"","wiki_title":"Fibroblast","match":"fibroblast|fibroblasten"},"monocyt":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyt|monocyten"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"beenmerg|het beenmerg"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"collageen":{"title":"Collageen","short":"Sterkste structuureiwit van het lichaam; hoofdbestanddeel van bindweefsel, dermis, pezen en bot.","definition":"<p><b>Collageen</b> is het meest voorkomende eiwit in het lichaam en vormt sterke, drievoudig gewonden vezels.</p><p>In de dermis geeft het de huid trekvastheid; fibroblasten maken het aan. Voor de aanmaak is vitamine C nodig (hydroxylering van proline).</p>","image_url":"","wiki_title":"Collagen","match":"collageen"},"elastine":{"title":"Elastine","short":"Rekbaar bindweefseleiwit dat huid, longen en bloedvaten na uitrekking hun vorm laat hervinden.","definition":"<p><b>Elastine</b> vormt elastische vezels die kunnen uitrekken en daarna weer terugveren.</p><p>Het geeft de huid, longen en slagaderwanden hun elasticiteit. Afname van elastine draagt bij aan huidveroudering en rimpels.</p>","image_url":"","wiki_title":"Elastin","match":"elastine"},"plaque":{"title":"Plaque","short":"Verheven, plateauvormige huidafwijking groter dan ~1 cm, vaak door samenvloeien van papels.","definition":"<p>Een <b>plaque</b> is een verheven, afgeplatte laesie groter dan ongeveer 1 cm — breder dan hoog.</p><p>Ze ontstaat vaak door het samenvloeien van papels en is typisch voor psoriasis.</p>","image_url":"","wiki_title":"Skin condition","match":"plaque|plaques"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"squama":{"title":"Squama","short":"Zichtbare hoornschilfer door versnelde of gestoorde verhoorning van de opperhuid.","definition":"<p>Een <b>squama</b> (schilfer) is een loskomend plaatje hoorncellen van het stratum corneum.</p><p>Overmatige schilfering is typerend voor psoriasis en ichthyosis.</p>","image_url":"","wiki_title":"Desquamation","match":"squama|squamae|schilfer|schilfering"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"acetylcholine":{"title":"Acetylcholine","short":"Acetylcholine is de neurotransmitter van de neuromusculaire overgang, van alle autonome ganglia en van het parasympathische zenuwstelsel.","definition":"<p><strong>Acetylcholine</strong> wordt gemaakt uit choline en acetyl-CoA en na afgifte snel afgebroken door <em>acetylcholinesterase</em>.</p><p>Het werkt op <em>nicotinerge</em> receptoren (ionkanalen: neuromusculaire eindplaat, autonome ganglia, bijniermerg) en <em>muscarinerge</em> receptoren (G-eiwitgekoppeld: doelorganen van het parasympathicus en de zweetklieren). Centraal speelt het een rol bij aandacht en geheugen; bij de ziekte van Alzheimer is er een cholinerg tekort.</p>","image_url":"","wiki_title":"Acetylcholine","match":"acetylcholine|ach","option_only":true},"vetzuren":{"title":"Vetzuren","short":"Vetzuren zijn koolstofketens met een carboxylgroep; ze worden via bèta-oxidatie in de mitochondriën verbrand en leveren veel ATP, maar alleen aeroob.","definition":"<p><strong>Vetzuren</strong> zijn lange koolwaterstofketens met een carboxylgroep, verzadigd of onverzadigd. Ze worden opgeslagen als triglyceriden in vetweefsel en bij behoefte door lipolyse vrijgemaakt.</p><p>In de cel worden ze met carnitine de mitochondriën in getransporteerd en via <em>bèta-oxidatie</em> afgebroken tot acetyl-CoA, dat de citroenzuurcyclus in gaat. Vetzuren leveren per gram veel meer energie dan glucose, maar alleen via zuurstofafhankelijke stofwisseling en relatief langzaam. In de lever kunnen ze ketonlichamen vormen.</p>","image_url":"","wiki_title":"Fatty acid","match":"vetzuren|vrije vetzuren|vetzuur|vetzuurverbranding|vetzuuroxidatie","option_only":true},"foliumzuur":{"title":"Foliumzuur","short":"Foliumzuur (vitamine B11/B9) is nodig voor DNA-synthese; tekort geeft megaloblastaire anemie en verhoogt het risico op een neuralebuisdefect.","definition":"<p><strong>Foliumzuur</strong> (folaat) is als tetrahydrofolaat een drager van één-koolstofgroepen, nodig voor de synthese van purines en thymidine en dus voor <em>DNA-synthese</em> en celdeling.</p><p>Tekort geeft een <em>megaloblastaire (macrocytaire) anemie</em>. Een tekort rond de conceptie verhoogt het risico op neuralebuisdefecten (spina bifida); daarom wordt vrouwen met kinderwens aangeraden vanaf 4 weken voor de conceptie tot 10 weken zwangerschap foliumzuur te slikken.</p>","image_url":"","wiki_title":"Folate","match":"foliumzuur|folaat|vitamine b11|vitamine b9","option_only":true},"n. musculocutaneus":{"title":"N. musculocutaneus","short":"De n. musculocutaneus (C5–C7) innerveert de flexoren van de bovenarm (m. biceps, m. brachialis, m. coracobrachialis) en de huid van de laterale onderarm.","definition":"<p>De <strong>n. musculocutaneus</strong> komt uit de fasciculus lateralis van de plexus brachialis (C5–C7). Hij doorboort de m. coracobrachialis en loopt tussen de m. biceps brachii en de m. brachialis.</p><p>Motorisch innerveert hij de voorste spiergroep van de bovenarm: <em>m. coracobrachialis, m. biceps brachii en m. brachialis</em> (flexie in de elleboog, supinatie). Zijn sensibele eindtak (n. cutaneus antebrachii lateralis) verzorgt de huid van de laterale onderarm.</p>","image_url":"","wiki_title":"Musculocutaneous nerve","match":"n. musculocutaneus|nervus musculocutaneus|n musculocutaneus","option_only":true},"n. axillaris":{"title":"N. axillaris","short":"De n. axillaris (C5–C6) innerveert de m. deltoideus en m. teres minor en de huid over de deltoideus; kwetsbaar bij een schouderluxatie of collum chirurgicum-fractuur.","definition":"<p>De <strong>n. axillaris</strong> ontspringt uit de fasciculus posterior van de plexus brachialis (C5–C6). Hij loopt door de laterale okselspleet (spatium quadrangulare) samen met de a. circumflexa humeri posterior, rond het collum chirurgicum van de humerus.</p><p>Hij innerveert de <em>m. deltoideus</em> (abductie van de arm voorbij ±15°) en de <em>m. teres minor</em> (exorotatie), en sensibel de huid over het onderste deel van de deltoideus (‘regimental badge area’). Letsel bij schouderluxatie of fractuur van het collum chirurgicum.</p>","image_url":"","wiki_title":"Axillary nerve","match":"n. axillaris|nervus axillaris|n axillaris","option_only":true},"n. ulnaris":{"title":"N. ulnaris","short":"De n. ulnaris (C8–T1) loopt achter de epicondylus medialis (‘telefoonbotje’) en innerveert de meeste intrinsieke handspieren en de huid van de pink.","definition":"<p>De <strong>n. ulnaris</strong> komt uit de fasciculus medialis van de plexus brachialis (C8–T1). Hij loopt achter de epicondylus medialis van de humerus door de sulcus nervi ulnaris en via het kanaal van Guyon naar de hand.</p><p>In de onderarm innerveert hij de m. flexor carpi ulnaris en het ulnaire deel van de m. flexor digitorum profundus; in de hand de meeste intrinsieke spieren (mm. interossei, hypothenar, mm. lumbricales III–IV, m. adductor pollicis). Sensibel: de pink en ulnaire helft van de ringvinger. Uitval geeft een klauwhand en een positief teken van Froment.</p>","image_url":"","wiki_title":"Ulnar nerve","match":"n. ulnaris|nervus ulnaris|n ulnaris","option_only":true},"n. radialis":{"title":"N. radialis","short":"De n. radialis (C5–T1) innerveert alle extensoren van boven- en onderarm; letsel (bijv. bij een humerusschachtfractuur) geeft een dropshand.","definition":"<p>De <strong>n. radialis</strong> is de grootste tak van de fasciculus posterior van de plexus brachialis (C5–T1). Hij loopt in de sulcus nervi radialis spiraalsgewijs om de achterkant van de humerusschacht.</p><p>Motorisch innerveert hij de <em>extensoren</em>: m. triceps brachii, m. brachioradialis, en via de r. profundus de extensoren van pols en vingers en de m. supinator. Sensibel verzorgt hij de achterzijde van arm en onderarm en de dorsale zijde van de radiale hand (eerste webspace). Letsel geeft een <em>dropshand</em>.</p>","image_url":"","wiki_title":"Radial nerve","match":"n. radialis|nervus radialis|n radialis","option_only":true},"n. suprascapularis":{"title":"N. suprascapularis","short":"De n. suprascapularis (C5–C6) innerveert de m. supraspinatus en m. infraspinatus.","definition":"<p>De <strong>n. suprascapularis</strong> komt uit de truncus superior van de plexus brachialis (C5–C6). Hij loopt over de schouder naar dorsaal en gaat door de incisura scapulae onder het lig. transversum scapulae superius.</p><p>Hij innerveert twee spieren van de rotator cuff: de <em>m. supraspinatus</em> (start van abductie) en de <em>m. infraspinatus</em> (exorotatie), en geeft sensibele takjes aan het schoudergewricht.</p>","image_url":"","wiki_title":"Suprascapular nerve","match":"n. suprascapularis|nervus suprascapularis","option_only":true},"a. axillaris":{"title":"A. axillaris","short":"De a. axillaris is de voortzetting van de a. subclavia vanaf de buitenrand van de eerste rib tot de onderrand van de m. teres major.","definition":"<p>De <strong>a. axillaris</strong> begint aan de laterale rand van de <em>eerste rib</em> als voortzetting van de a. subclavia en eindigt aan de onderrand van de m. teres major, waarna zij a. brachialis heet.</p><p>De m. pectoralis minor verdeelt haar in drie delen, die samen zes takken afgeven: a. thoracica superior, a. thoracoacromialis, a. thoracica lateralis, a. subscapularis en de aa. circumflexae humeri anterior en posterior. De fasciculi van de plexus brachialis liggen om haar heen.</p>","image_url":"","wiki_title":"Axillary artery","match":"a. axillaris|arteria axillaris","option_only":true},"a. subclavia":{"title":"A. subclavia","short":"De a. subclavia voorziet de arm, een deel van de hals en het brein (via de a. vertebralis) van bloed; rechts uit de truncus brachiocephalicus, links direct uit de aortaboog.","definition":"<p>De <strong>a. subclavia</strong> ontspringt rechts uit de truncus brachiocephalicus en links direct uit de aortaboog. Zij loopt over de eerste rib achter de m. scalenus anterior (scalenusspleet, samen met de plexus brachialis).</p><p>Belangrijke takken: <em>a. vertebralis</em> (naar het brein), a. thoracica interna, truncus thyrocervicalis en truncus costocervicalis. Aan de buitenrand van de eerste rib gaat zij over in de a. axillaris.</p>","image_url":"","wiki_title":"Subclavian artery","match":"a. subclavia|arteria subclavia","option_only":true},"a. ulnaris":{"title":"A. ulnaris","short":"De a. ulnaris is een van de twee eindtakken van de a. brachialis en loopt aan de ulnaire zijde van de onderarm naar de hand, waar zij vooral de oppervlakkige handboog vormt.","definition":"<p>De <strong>a. ulnaris</strong> ontstaat in de fossa cubiti uit de a. brachialis (samen met de a. radialis). Zij loopt diep aan de ulnaire zijde van de onderarm en daarna via het kanaal van Guyon naar de hand.</p><p>Vlak na haar oorsprong geeft zij de a. interossea communis af. In de hand vormt zij vooral de <em>arcus palmaris superficialis</em>. De doorgankelijkheid wordt getest met de test van Allen.</p>","image_url":"","wiki_title":"Ulnar artery","match":"a. ulnaris|arteria ulnaris","option_only":true},"gladde spiercellen":{"title":"Gladde spiercellen","short":"Gladde spiercellen zijn spoelvormige, onwillekeurig aangestuurde spiercellen zonder dwarsstreping, in de wand van vaten en holle organen.","definition":"<p><strong>Gladde spiercellen</strong> zijn spoelvormige cellen met één centraal gelegen kern. Actine en myosine liggen niet in sarcomeren, daarom ontbreekt de dwarsstreping. Contractie wordt via calcium-calmoduline en myosine-lichteketenkinase gereguleerd.</p><p>Ze komen voor in de wand van bloedvaten, luchtwegen, maag-darmkanaal, blaas en uterus en worden aangestuurd door het autonome zenuwstelsel, hormonen en lokale factoren. Ze kunnen langdurig samentrekken met weinig energieverbruik.</p>","image_url":"","wiki_title":"Smooth muscle","match":"gladde spiercellen|glad spierweefsel|gladde spier|gladde spiercel","option_only":true},"dwarsgestreept skeletspierweefsel":{"title":"Dwarsgestreept skeletspierweefsel","short":"Skeletspierweefsel bestaat uit lange, meerkernige spiervezels met dwarsstreping door sarcomeren; het wordt willekeurig aangestuurd.","definition":"<p><strong>Dwarsgestreept skeletspierweefsel</strong> bestaat uit spiervezels: zeer lange cellen met vele, aan de rand gelegen kernen, ontstaan door fusie van myoblasten.</p><p>De regelmatige rangschikking van actine en myosine in <em>sarcomeren</em> geeft de dwarsstreping. Contractie start na prikkeling door een motorneuron (acetylcholine op de eindplaat) en calciumafgifte uit het sarcoplasmatisch reticulum. Herstel na schade verloopt via satellietcellen.</p>","image_url":"","wiki_title":"Skeletal muscle","match":"dwarsgestreept skeletspierweefsel|skeletspierweefsel|skeletspier|dwarsgestreepte spier|skeletspieren","option_only":true},"losmazig bindweefsel":{"title":"Losmazig bindweefsel","short":"Losmazig bindweefsel is los georganiseerd bindweefsel met veel grondsubstantie, cellen en weinig vezels; het vult ruimtes en draagt vaten en zenuwen.","definition":"<p><strong>Losmazig bindweefsel</strong> bevat relatief veel grondsubstantie en cellen (fibroblasten, macrofagen, mestcellen, leukocyten) en een los netwerk van collagene en elastische vezels.</p><p>Het ligt onder epitheel (bijv. lamina propria van slijmvliezen, papillaire dermis), rond bloedvaten en zenuwen en tussen organen. Het is flexibel, goed doorbloed en een belangrijke plaats voor afweer en oedeemvorming. Ter vergelijking: straf bindweefsel (pezen, banden) bestaat vooral uit dicht opeengepakte collagene vezels.</p>","image_url":"","wiki_title":"Loose connective tissue","match":"losmazig bindweefsel|los bindweefsel|areolair bindweefsel","option_only":true},"elastisch kraakbeen":{"title":"Elastisch kraakbeen","short":"Elastisch kraakbeen is kraakbeen met veel elastische vezels, waardoor het buigzaam is; het zit o.a. in de oorschelp en de epiglottis.","definition":"<p><strong>Elastisch kraakbeen</strong> lijkt op hyalien kraakbeen, maar de matrix bevat daarnaast een dicht netwerk van <em>elastische vezels</em>. Het is omgeven door perichondrium.</p><p>Het is buigzaam en veert terug in zijn vorm. Het komt voor in de oorschelp, de uitwendige gehoorgang, de buis van Eustachius, de epiglottis en enkele kleine kraakbeentjes van de larynx.</p>","image_url":"","wiki_title":"Elastic cartilage","match":"elastisch kraakbeen","option_only":true},"draaigewricht":{"title":"Draaigewricht","short":"Een draaigewricht laat alleen rotatie om één as toe, zoals het gewricht tussen atlas en dens van de axis of het proximale radio-ulnaire gewricht.","definition":"<p>Een <strong>draaigewricht</strong> (articulatio trochoidea) is een eenassig gewricht waarbij een cilindervormig botdeel draait binnen een ring van bot en ligament.</p><p>Voorbeelden: het gewricht tussen de <em>dens axis</em> en de atlas (hoofd draaien, ‘nee’ schudden) en het <em>proximale radio-ulnaire gewricht</em>, waarin de radiuskop draait binnen het lig. anulare (pro- en supinatie).</p>","image_url":"","wiki_title":"Pivot joint","match":"draaigewricht|articulatio trochoidea|rolgewricht","option_only":true},"epifyse":{"title":"Epifyse","short":"De epifyse is het uiteinde van een pijpbeen, of de pijnappelklier (glandula pinealis) die melatonine maakt — het woord heeft twee betekenissen.","definition":"<p>Bij een <strong>pijpbeen</strong> is de epifyse het verbrede uiteinde, bedekt met gewrichtskraakbeen. Bij kinderen ligt tussen epifyse en metafyse de groeischijf (epifysairschijf), waar het bot in de lengte groeit; na de puberteit sluit die.</p><p>In de hersenen wordt met <strong>epifyse</strong> ook de <em>glandula pinealis</em> (pijnappelklier) bedoeld, een onderdeel van de epithalamus dat in het donker melatonine afgeeft en zo het dag-nachtritme ondersteunt.</p>","image_url":"","wiki_title":"Epiphysis","match":"epifyse|epiphysis","option_only":true},"oorschelp":{"title":"Oorschelp","short":"De oorschelp is het uitwendige oor van elastisch kraakbeen en huid; hij vangt geluid op en helpt bij het lokaliseren van geluid.","definition":"<p>De <strong>oorschelp</strong> (auricula) bestaat uit een plaat <em>elastisch kraakbeen</em> bedekt met huid; alleen de oorlel bevat geen kraakbeen maar vet en bindweefsel.</p><p>De plooien (helix, antihelix, tragus, concha) vangen geluid op en leiden het naar de uitwendige gehoorgang; door hun vorm helpen ze bij het bepalen of een geluid van voren, achteren, boven of onder komt.</p>","image_url":"","wiki_title":"Auricle (anatomy)","match":"oorschelp|auricula|pinna","option_only":true},"het oor":{"title":"Het oor","short":"Het oor bestaat uit buiten-, midden- en binnenoor en verzorgt het gehoor en het evenwicht.","definition":"<p>Het <strong>oor</strong> is opgebouwd uit drie delen. Het <em>buitenoor</em> (oorschelp en gehoorgang) vangt geluid op; het <em>middenoor</em> (trommelvlies en gehoorbeentjes hamer, aambeeld en stijgbeugel) versterkt de trillingen; het <em>binnenoor</em> zet ze om in zenuwsignalen.</p><p>Het binnenoor bevat het slakkenhuis (cochlea) voor het gehoor en het vestibulaire systeem (halfcirkelvormige kanalen, utriculus en sacculus) voor evenwicht. Signalen lopen via de n. vestibulocochlearis (VIII) naar de hersenstam.</p>","image_url":"","wiki_title":"Ear","match":"het oor|oor","option_only":true},"hypertensie":{"title":"Hypertensie","short":"Hypertensie is een blijvend verhoogde bloeddruk (≥140/90 mmHg op het spreekuur); een belangrijke risicofactor voor hart- en vaatziekten.","definition":"<p>Bij <strong>hypertensie</strong> is de bloeddruk herhaaldelijk verhoogd: op het spreekuur ≥140/90 mmHg. Meestal is er geen aanwijsbare oorzaak (<em>primaire/essentiële</em> hypertensie); bij een minderheid is er een secundaire oorzaak, zoals nierziekte, nierarteriestenose, hyperaldosteronisme of feochromocytoom.</p><p>Hypertensie geeft meestal geen klachten, maar beschadigt op termijn vaten en organen: linkerventrikelhypertrofie, hartfalen, CVA, nierschade en retinopathie. Behandeling: leefstijl (zout, gewicht, beweging, alcohol) en medicatie (o.a. diuretica, ACE-remmers/ARB's, calciumantagonisten).</p>","image_url":"","wiki_title":"Hypertension","match":"hypertensie|hoge bloeddruk|arteriële hypertensie","option_only":true},"m. bechterew (ankylosing spondylitis)":{"title":"Ziekte van Bechterew (spondylitis ankylopoetica)","short":"De ziekte van Bechterew is een chronische ontsteking van de wervelkolom en SI-gewrichten, vaak bij jonge mannen met HLA-B27, met ochtendstijfheid en lage rugpijn.","definition":"<p>De <strong>ziekte van Bechterew</strong> is een axiale spondyloartritis: een chronische ontsteking van de <em>sacro-iliacale gewrichten</em> en de wervelkolom, met name de aanhechtingen van banden en pezen (enthesitis).</p><p>Ze begint meestal voor het 40e jaar met inflammatoire lage rugpijn: ochtendstijfheid, verbetering bij bewegen, ’s nachts pijn. Er is een sterke associatie met <em>HLA-B27</em>. Op termijn kan verbening de wervelkolom verstijven (‘bamboo spine’). Extra-articulair: uveïtis anterior, IBD en psoriasis.</p>","image_url":"","wiki_title":"Ankylosing spondylitis","match":"m. bechterew (ankylosing spondylitis)|m. bechterew|ziekte van bechterew|ankylosing spondylitis|spondylitis ankylopoetica|axiale spondyloartritis","option_only":true},"artrose (osteoarthritis)":{"title":"Artrose","short":"Artrose is degeneratie van gewrichtskraakbeen met botreactie; het geeft startpijn en pijn bij belasting, vooral in knieën, heupen en handen bij ouderen.","definition":"<p>Bij <strong>artrose</strong> slijt en verdwijnt het gewrichtskraakbeen, met reactieve veranderingen van het bot: <em>osteofyten</em>, subchondrale sclerose en cysten, en versmalling van de gewrichtsspleet op de röntgenfoto.</p><p>Risicofactoren: leeftijd, overgewicht, eerder letsel en aanleg. Klachten: pijn bij belasting, startpijn en korte ochtendstijfheid (&lt;30 minuten), soms crepitaties en verminderde beweeglijkheid. Typische plaatsen: knie, heup, DIP- en PIP-gewrichten (Heberden- en Bouchardknobbels) en het CMC-1-gewricht.</p>","image_url":"","wiki_title":"Osteoarthritis","match":"artrose (osteoarthritis)|artrose|osteoarthritis|osteoartrose","option_only":true},"septische artritis":{"title":"Septische artritis","short":"Septische artritis is een bacteriële infectie van een gewricht (vaak S. aureus): acuut, pijnlijk, gezwollen, warm gewricht met koorts; een spoedgeval.","definition":"<p>Bij <strong>septische artritis</strong> raakt een gewricht geïnfecteerd, meestal via de bloedbaan, soms na een punctie of operatie. De meest voorkomende verwekker is <em>Staphylococcus aureus</em>; bij seksueel actieve jongvolwassenen ook <em>Neisseria gonorrhoeae</em>.</p><p>Het geeft een acuut rood, warm, gezwollen en zeer pijnlijk gewricht (vaak de knie) met bewegingsbeperking en meestal koorts. Diagnose door punctie (troebel synoviaal vocht met veel leukocyten, kweek). Snel draineren en antibiotica zijn nodig om kraakbeenvernietiging te voorkomen.</p>","image_url":"","wiki_title":"Septic arthritis","match":"septische artritis|bacteriële artritis|septische arthritis","option_only":true},"reactieve artritis":{"title":"Reactieve artritis","short":"Reactieve artritis is een steriele gewrichtsontsteking enkele weken na een darm- of urogenitale infectie, vaak bij HLA-B27-dragers.","definition":"<p><strong>Reactieve artritis</strong> ontstaat 1–4 weken na een infectie van de darm (<em>Salmonella</em>, <em>Shigella</em>, <em>Campylobacter</em>, <em>Yersinia</em>) of de urogenitale tractus (<em>Chlamydia trachomatis</em>). Het gewricht zelf is niet geïnfecteerd.</p><p>Typisch is een asymmetrische oligoartritis van vooral de benen, eventueel met enthesitis, dactylitis, urethritis en conjunctivitis/uveïtis. Het behoort tot de spondyloartritiden en is geassocieerd met HLA-B27.</p>","image_url":"","wiki_title":"Reactive arthritis","match":"reactieve artritis|reactieve arthritis|ziekte van reiter","option_only":true},"tumor":{"title":"Tumor","short":"Een tumor (neoplasma) is een gezwel door autonome, overmatige celgroei; die kan goedaardig (benigne) of kwaadaardig (maligne) zijn.","definition":"<p>In de pathologie betekent <strong>tumor</strong> letterlijk zwelling, maar meestal bedoelt men een <em>neoplasma</em>: weefsel dat ontstaat door celgroei die niet meer gereguleerd wordt en doorgaat zonder de oorspronkelijke prikkel.</p><p>Benigne tumoren groeien meestal langzaam en expansief, zijn goed begrensd en zaaien niet uit. Maligne tumoren groeien invasief en kunnen metastaseren. ‘Tumor’ is ook een van de klassieke ontstekingsverschijnselen (zwelling).</p>","image_url":"","wiki_title":"","match":"tumor|gezwel|neoplasma","option_only":true},"diarree":{"title":"Diarree","short":"Diarree is het vaker dan normaal (≥3x per dag) produceren van brijige tot waterdunne ontlasting.","definition":"<p><strong>Diarree</strong> betekent een verhoogde frequentie (meestal ≥3 keer per dag) en verminderde consistentie van de ontlasting. Acute diarree (&lt;2 weken) is meestal infectieus (virussen zoals norovirus, bacteriën, parasieten).</p><p>Mechanismen: <em>secretoir</em> (bijv. door toxines zoals choleratoxine), <em>osmotisch</em> (bijv. lactose-intolerantie, laxantia), <em>inflammatoir</em> (bijv. IBD, invasieve bacteriën, met bloed en slijm) en versnelde motiliteit. Het belangrijkste risico is uitdroging en elektrolytverlies.</p>","image_url":"","wiki_title":"Diarrhea","match":"diarree","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"de milt":{"title":"Milt","short":"De milt filtert het bloed: hij ruimt oude en beschadigde rode bloedcellen op en vormt een afweerorgaan tegen bacteriën in het bloed.","definition":"<p>De <strong>milt</strong> ligt linksboven in de buik onder het diafragma. Ze bestaat uit <em>rode pulpa</em> (sinusoïden waar verouderde of afwijkende erytrocyten worden afgebroken) en <em>witte pulpa</em> (lymfatisch weefsel met B- en T-cellen rond arteriolen).</p><p>De milt is belangrijk voor de afweer tegen <em>gekapselde bacteriën</em> (pneumokok, meningokok, H. influenzae). Na splenectomie is het risico op een ernstige sepsis daardoor verhoogd; deze patiënten worden gevaccineerd.</p>","image_url":"","wiki_title":"Spleen","match":"de milt|milt|lien|splenomegalie","option_only":true},"de navelstreng":{"title":"Navelstreng","short":"De navelstreng verbindt de foetus met de placenta en bevat normaal twee navelarteriën en één navelvene, ingebed in gelei van Wharton.","definition":"<p>De <strong>navelstreng</strong> bevat normaal <em>twee aa. umbilicales</em>, die zuurstofarm bloed van de foetus naar de placenta voeren, en <em>één v. umbilicalis</em>, die zuurstofrijk bloed naar de foetus terugbrengt. De vaten liggen in gelei van Wharton, omgeven door amnion.</p><p>Na de geboorte sluiten de vaten: de navelvene wordt het lig. teres hepatis en de navelarteriën de mediale umbilicale plooien. Een navelstreng met één arterie is geassocieerd met aangeboren afwijkingen.</p>","image_url":"","wiki_title":"Umbilical cord","match":"de navelstreng|navelstreng|funiculus umbilicalis","option_only":true},"depressieve stoornis":{"title":"Depressieve stoornis","short":"Een depressieve stoornis kenmerkt zich door minstens twee weken een sombere stemming en/of verlies van interesse en plezier, met o.a. slaap-, eetlust- en concentratieproblemen.","definition":"<p>Voor een <strong>depressieve stoornis</strong> (DSM-5) moeten gedurende minstens twee weken vijf of meer symptomen aanwezig zijn, waaronder ten minste één kernsymptoom: <em>depressieve stemming</em> of <em>verlies van interesse of plezier</em> (anhedonie).</p><p>Andere symptomen: veranderde eetlust of gewicht, slapeloosheid of juist veel slapen, psychomotorische remming of agitatie, vermoeidheid, schuldgevoelens of waardeloosheid, concentratieproblemen en gedachten aan de dood. Behandeling met psychotherapie en/of antidepressiva.</p>","image_url":"","wiki_title":"Major depressive disorder","match":"depressieve stoornis|depressie|depressieve episode|majeure depressie","option_only":true},"fibula":{"title":"Fibula","short":"De fibula (kuitbeen) is het dunne, laterale bot van het onderbeen; het draagt weinig gewicht maar vormt de laterale malleolus van de enkel.","definition":"<p>De <strong>fibula</strong> ligt lateraal van de tibia. Het caput fibulae articuleert met de tibia onder de knie, maar maakt geen deel uit van het kniegewricht. Distaal vormt de fibula de <em>malleolus lateralis</em>, onderdeel van de enkelvork.</p><p>Het bot is vooral een aanhechtingsplaats voor spieren en draagt weinig lichaamsgewicht. De n. fibularis communis loopt vlak om het collum fibulae heen en is daar kwetsbaar (klapvoet bij letsel of druk).</p>","image_url":"","wiki_title":"Fibula","match":"fibula|kuitbeen","option_only":true},"blaas":{"title":"Blaas (vesica urinaria)","short":"De blaas is een gespierd hol orgaan in het kleine bekken dat urine verzamelt en bij mictie leegt.","definition":"<p>De <strong>blaas</strong> ligt achter de symfyse. De wand bestaat uit urotheel (overgangsepitheel), dat zich aanpast aan de vullingsgraad, en de m. detrusor (gladde spier). Het driehoekige trigonum ligt tussen de twee ureteruitmondingen en de urethra-opening. Vulling en lediging worden gestuurd door autonome en willekeurige zenuwen (parasympathisch: contractie van de detrusor).</p>","image_url":"","wiki_title":"Urinary bladder","match":"blaas|urineblaas|vesica urinaria","option_only":true},"creatinine":{"title":"Creatinine","short":"Creatinine is een afbraakproduct van creatinefosfaat uit spieren; de bloedwaarde wordt gebruikt om de nierfunctie te schatten.","definition":"<p><strong>Creatinine</strong> ontstaat in een vrij constant tempo uit creatine in spieren en wordt vooral door glomerulaire filtratie uitgescheiden. Daarom stijgt de serumwaarde als de nierfunctie (GFR) daalt; op basis van creatinine, leeftijd en geslacht wordt de eGFR berekend. Spiermassa beïnvloedt de waarde: bij weinig spiermassa kan een normaal creatinine een verminderde nierfunctie maskeren.</p>","image_url":"","wiki_title":"Creatinine","match":"creatinine|kreatinine|serumcreatinine","option_only":true},"glycogeen":{"title":"Glycogeen","short":"Glycogeen is de opslagvorm van glucose in lever en spier: een sterk vertakt polymeer van glucose-eenheden.","definition":"<p><strong>Glycogeen</strong> bestaat uit glucose-eenheden met α-1,4-bindingen en vertakkingen via α-1,6-bindingen. Glycogeensynthase bouwt het op (gestimuleerd door insuline), glycogeenfosforylase breekt het af (gestimuleerd door glucagon en adrenaline). Leverglycogeen houdt de bloedglucose op peil; spierglycogeen dient alleen de spier zelf.</p>","image_url":"","wiki_title":"Glycogen","match":"glycogeen","option_only":true},"kogelgewricht":{"title":"Kogelgewricht","short":"Een kogelgewricht is een drieassig synoviaal gewricht met een bolle kop in een kom, zoals heup en schouder.","definition":"<p>Bij een <strong>kogelgewricht</strong> (articulatio spheroidea) past een bolvormige gewrichtskop in een holle kom. Beweging is mogelijk om drie assen: flexie/extensie, abductie/adductie en rotatie (en daarmee circumductie). Voorbeelden zijn het heupgewricht (diepe kom, stabiel) en het schoudergewricht (ondiepe kom, zeer beweeglijk maar minder stabiel).</p>","image_url":"","wiki_title":"Ball-and-socket joint","match":"kogelgewricht|articulatio spheroidea|bolgewricht","option_only":true},"zadelgewricht":{"title":"Zadelgewricht","short":"Een zadelgewricht is een tweeassig gewricht waarvan beide gewrichtsvlakken zadelvormig zijn, zoals het CMC-1-gewricht van de duim.","definition":"<p>Bij een <strong>zadelgewricht</strong> (articulatio sellaris) zijn beide gewrichtsvlakken in de ene richting bol en in de andere richting hol, als twee zadels die op elkaar passen. Er is beweging mogelijk om twee assen. Het klassieke voorbeeld is het carpometacarpale gewricht van de duim, dat oppositie mogelijk maakt.</p>","image_url":"","wiki_title":"Saddle joint","match":"zadelgewricht|articulatio sellaris","option_only":true},"ellipsoid gewricht":{"title":"Ellipsoïd gewricht","short":"Een ellipsoïd gewricht (eigewricht) is een tweeassig gewricht met een ovale kop in een ovale kom, zoals het radiocarpale gewricht.","definition":"<p>Bij een <strong>ellipsoïd gewricht</strong> (articulatio ellipsoidea) past een eivormige, bolle gewrichtskop in een ovale kom. Er is beweging mogelijk om twee assen (flexie/extensie en abductie/adductie), maar geen echte rotatie. Voorbeelden zijn het radiocarpale (pols)gewricht en het atlanto-occipitale gewricht.</p>","image_url":"","wiki_title":"Condyloid joint","match":"ellipsoid gewricht|ellipsoïd gewricht|eigewricht|articulatio ellipsoidea","option_only":true},"vlak gewricht":{"title":"Vlak gewricht","short":"Een vlak gewricht heeft (vrijwel) vlakke gewrichtsvlakken die alleen kleine glijbewegingen toestaan.","definition":"<p>Bij een <strong>vlak gewricht</strong> (articulatio plana) glijden twee vrijwel vlakke gewrichtsvlakken langs elkaar. De beweeglijkheid is klein en wordt beperkt door kapsel en banden. Voorbeelden zijn de facetgewrichten van de wervelkolom, het acromioclaviculaire gewricht en gewrichten tussen de handwortelbeentjes.</p>","image_url":"","wiki_title":"Plane joint","match":"vlak gewricht|articulatio plana|glijgewricht","option_only":true},"articulatio coxae":{"title":"Heupgewricht (articulatio coxae)","short":"Het heupgewricht is een kogelgewricht tussen de femurkop en het acetabulum van het bekken.","definition":"<p>De <strong>articulatio coxae</strong> verbindt de caput femoris met het acetabulum. Het diepe acetabulum, het labrum en sterke banden (lig. iliofemorale, pubofemorale en ischiofemorale) maken het een zeer stabiel gewricht. De femurkop wordt vooral doorbloed via de aa. circumflexae femoris; bij een mediale collumfractuur dreigt daardoor avasculaire necrose.</p>","image_url":"","wiki_title":"Hip","match":"articulatio coxae|heupgewricht","option_only":true},"tussenwervelschijf":{"title":"Tussenwervelschijf (discus intervertebralis)","short":"De tussenwervelschijf ligt tussen twee wervellichamen en bestaat uit een vezelige ring met een geleiachtige kern; ze vangt schokken op.","definition":"<p>Een <strong>tussenwervelschijf</strong> bestaat uit de <em>annulus fibrosus</em> (concentrische lagen vezelig kraakbeen) en de centrale <em>nucleus pulposus</em> (waterrijke gel, restant van de chorda dorsalis). Ze verdeelt druk en maakt beweging tussen wervels mogelijk. Bij degeneratie verliest de schijf water; een scheur in de annulus kan leiden tot een hernia nuclei pulposi.</p>","image_url":"","wiki_title":"Intervertebral disc","match":"tussenwervelschijf|discus intervertebralis|tussenwervelschijven","option_only":true},"hyalien kraakbeen":{"title":"Hyalien kraakbeen","short":"Hyalien kraakbeen is het meest voorkomende kraakbeen: glad en drukbestendig, met collageen type II; het bekleedt gewrichtsvlakken.","definition":"<p><strong>Hyalien kraakbeen</strong> bestaat uit chondrocyten in lacunes, omgeven door een matrix van collageen type II en proteoglycanen die veel water binden. Het heeft geen bloedvaten en wordt gevoed via diffusie. Het komt voor als gewrichtskraakbeen, in de ribben, de luchtwegen en als groeischijf; ook het embryonale skelet is grotendeels hyalien kraakbeen.</p>","image_url":"","wiki_title":"Hyaline cartilage","match":"hyalien kraakbeen|hyaliene kraakbeen","option_only":true},"elastinevezels":{"title":"Elastinevezels","short":"Elastinevezels zijn rekbare vezels in de extracellulaire matrix die weefsel na uitrekking terug laten veren.","definition":"<p><strong>Elastische vezels</strong> bestaan uit een kern van elastine omgeven door microfibrillen van fibrilline. Ze kunnen tot ongeveer anderhalf keer hun lengte uitrekken en daarna terugveren. Ze komen veel voor in de wand van grote arteriën, longen, huid en elastisch kraakbeen. Mutaties in fibrilline geven het syndroom van Marfan.</p>","image_url":"","wiki_title":"Elastic fiber","match":"elastinevezels|elastische vezels|elastine","option_only":true},"elastisch bindweefsel":{"title":"Elastisch bindweefsel","short":"Elastisch bindweefsel bevat veel elastische vezels en komt voor waar weefsel moet kunnen rekken en terugveren.","definition":"<p><strong>Elastisch bindweefsel</strong> bestaat grotendeels uit parallel of netvormig gerangschikte elastische vezels. Het komt voor in de wand van grote (elastische) arteriën zoals de aorta, in de ligamenta flava tussen de wervelbogen en in het lig. nuchae. Het zorgt voor veerkracht, zoals de windketelfunctie van de aorta.</p>","image_url":"","wiki_title":"Elastic fiber","match":"elastisch bindweefsel","option_only":true},"geordend straf bindweefsel":{"title":"Geordend straf bindweefsel","short":"Geordend straf bindweefsel bestaat uit dicht opeengepakte, parallel lopende collageenvezels en is erg trekvast in één richting.","definition":"<p>In <strong>geordend straf bindweefsel</strong> liggen collageen type I-vezels parallel, met daartussen rijen fibroblasten (tenocyten). Het weefsel is zeer sterk in de lengterichting maar weinig doorbloed, waardoor het traag herstelt. Het vormt pezen, ligamenten en aponeurosen.</p>","image_url":"","wiki_title":"Dense regular connective tissue","match":"geordend straf bindweefsel|regelmatig straf bindweefsel","option_only":true},"ongeordend straf bindweefsel":{"title":"Ongeordend straf bindweefsel","short":"Ongeordend straf bindweefsel heeft dicht opeengepakte collageenvezels in alle richtingen en weerstaat trekkracht vanuit elke kant.","definition":"<p>In <strong>ongeordend straf bindweefsel</strong> lopen de collageenvezels in een dicht netwerk in verschillende richtingen. Daardoor is het bestand tegen krachten uit allerlei richtingen. Het komt voor in de reticulaire dermis, orgaankapsels, periost, perichondrium en de dura mater.</p>","image_url":"","wiki_title":"Dense irregular connective tissue","match":"ongeordend straf bindweefsel|onregelmatig straf bindweefsel","option_only":true},"mesenchymale cellen":{"title":"Mesenchymale cellen","short":"Mesenchymale cellen zijn embryonale, ongedifferentieerde bindweefselcellen waaruit o.a. bot, kraakbeen, spier en bindweefsel ontstaan.","definition":"<p><strong>Mesenchym</strong> is los embryonaal bindweefsel, grotendeels afkomstig van het mesoderm. De stervormige mesenchymale cellen kunnen differentiëren tot fibroblasten, chondroblasten, osteoblasten, adipocyten, gladde spiercellen en endotheel. Ook bij volwassenen bestaan nog mesenchymale stamcellen, o.a. in het beenmerg.</p>","image_url":"","wiki_title":"Mesenchyme","match":"mesenchymale cellen|mesenchym|mesenchymale stamcellen","option_only":true},"osteoprogenitorcel":{"title":"Osteoprogenitorcel","short":"Osteoprogenitorcellen zijn voorlopercellen in periost en endost die kunnen uitgroeien tot osteoblasten.","definition":"<p><strong>Osteoprogenitorcellen</strong> zijn afgeleid van mesenchymale stamcellen en liggen in de binnenste laag van het periost, in het endost en langs de kanalen van Havers. Onder invloed van o.a. RUNX2 en mechanische belasting differentiëren ze tot osteoblasten, wat belangrijk is bij botgroei en fractuurgenezing.</p>","image_url":"","wiki_title":"Osteoprogenitor cell","match":"osteoprogenitorcel|osteoprogenitorcellen|osteoprogenitor","option_only":true},"osteoclast":{"title":"Osteoclast","short":"Een osteoclast is een grote, meerkernige cel die botweefsel afbreekt (botresorptie).","definition":"<p><strong>Osteoclasten</strong> ontstaan uit de monocyt-macrofaaglijn door fusie van voorlopercellen. Ze hechten aan het botoppervlak en vormen een afgesloten ruimte onder een geplooide rand (ruffled border), waarin ze zuur en enzymen (o.a. cathepsine K) uitscheiden. Ze worden geactiveerd via RANKL en geremd door osteoprotegerine en calcitonine; bisfosfonaten remmen hun werking.</p>","image_url":"","wiki_title":"Osteoclast","match":"osteoclast|osteoclasten","option_only":true},"hydroxyapathiet":{"title":"Hydroxyapatiet","short":"Hydroxyapatiet is het calciumfosfaatkristal dat bot en tandglazuur hun hardheid geeft.","definition":"<p><strong>Hydroxyapatiet</strong> (Ca₁₀(PO₄)₆(OH)₂) vormt het anorganische deel van botmatrix, ongeveer twee derde van het botgewicht. De kristallen liggen tussen en op de collageen type I-vezels; collageen geeft trekvastheid, hydroxyapatiet drukvastheid. Fluoride kan de hydroxylgroep vervangen tot het zuurbestendiger fluorapatiet.</p>","image_url":"","wiki_title":"Hydroxyapatite","match":"hydroxyapathiet|hydroxyapatiet","option_only":true},"tibia":{"title":"Tibia (scheenbeen)","short":"De tibia is het grote, gewichtdragende bot aan de mediale zijde van het onderbeen.","definition":"<p>De <strong>tibia</strong> vormt met de femur het kniegewricht (via de condylus medialis en lateralis van het tibiaplateau) en met de talus het bovenste spronggewricht; distaal vormt zij de malleolus medialis. De voorrand ligt direct onder de huid. Aan de tuberositas tibiae hecht de patellapees.</p>","image_url":"","wiki_title":"Tibia","match":"tibia|scheenbeen","option_only":true},"femur":{"title":"Femur (dijbeen)","short":"De femur is het langste en sterkste bot van het lichaam, tussen heup en knie.","definition":"<p>De <strong>femur</strong> heeft proximaal de femurkop, het collum en de trochanter major en minor, en distaal de condylus medialis en lateralis. Het collum maakt een hoek met de schacht (collodiafysaire hoek). Collumfracturen komen veel voor bij ouderen met osteoporose; de bloedvoorziening van de kop kan daarbij in gevaar komen.</p>","image_url":"","wiki_title":"Femur","match":"femur|dijbeen","option_only":true},"ulna":{"title":"Ulna (ellepijp)","short":"De ulna is het mediale bot van de onderarm (aan de pinkzijde); proximaal vormt het de punt van de elleboog.","definition":"<p>De <strong>ulna</strong> heeft proximaal het olecranon en het processus coronoideus, die samen de incisura trochlearis vormen voor het scharniergewricht met de humerus. Distaal heeft zij een kop en een processus styloideus. Samen met de radius maakt zij pro- en supinatie mogelijk via de proximale en distale radio-ulnaire gewrichten.</p>","image_url":"","wiki_title":"Ulna","match":"ulna|ellepijp","option_only":true},"radius":{"title":"Radius (spaakbeen)","short":"De radius is het laterale bot van de onderarm (aan de duimzijde) dat distaal het grootste deel van het polsgewricht vormt.","definition":"<p>De <strong>radius</strong> heeft proximaal een schijfvormige kop die draait in het lig. anulare, en distaal een brede basis die articuleert met de handwortel. Bij pronatie draait de radius om de ulna heen. Een distale radiusfractuur is een van de meest voorkomende fracturen, vaak na een val op de uitgestrekte hand.</p>","image_url":"","wiki_title":"Radius (bone)","match":"radius|spaakbeen","option_only":true},"os lunatum":{"title":"Os lunatum","short":"Het os lunatum is het maanvormige handwortelbeentje in het midden van de proximale rij.","definition":"<p>Het <strong>os lunatum</strong> ligt tussen het os scaphoideum en het os triquetrum en articuleert met de radius. Het kan na een hyperextensietrauma naar palmair luxeren en dan de n. medianus in de carpale tunnel comprimeren. Avasculaire necrose van het lunatum heet de ziekte van Kienböck.</p>","image_url":"","wiki_title":"Lunate bone","match":"os lunatum|maanvormig been","option_only":true},"os pisiforme":{"title":"Os pisiforme","short":"Het os pisiforme is een klein, erwtvormig handwortelbeentje aan de pinkzijde, een sesambeen in de pees van de m. flexor carpi ulnaris.","definition":"<p>Het <strong>os pisiforme</strong> ligt palmair op het os triquetrum en is goed voelbaar aan de ulnaire zijde van de pols. Het is een sesambeentje in de pees van de m. flexor carpi ulnaris en vormt een begrenzing van het kanaal van Guyon, waardoor de n. en a. ulnaris lopen.</p>","image_url":"","wiki_title":"Pisiform bone","match":"os pisiforme|erwtvormig been","option_only":true},"os hamatum":{"title":"Os hamatum","short":"Het os hamatum is een handwortelbeentje in de distale rij aan de pinkzijde, met een haakvormig uitsteeksel (hamulus).","definition":"<p>Het <strong>os hamatum</strong> articuleert met de vierde en vijfde middenhandsbeentjes. De <em>hamulus</em> is een aanhechtingspunt voor het retinaculum flexorum en begrenst het kanaal van Guyon. Een fractuur van de hamulus komt voor bij golf-, tennis- en honkbalspelers.</p>","image_url":"","wiki_title":"Hamate bone","match":"os hamatum|haakvormig been","option_only":true},"os sacrum":{"title":"Os sacrum (heiligbeen)","short":"Het os sacrum is het driehoekige bot uit vijf vergroeide sacrale wervels dat de achterwand van het bekken vormt.","definition":"<p>Het <strong>os sacrum</strong> articuleert boven met de vijfde lendenwervel, aan beide zijden met de ossa ilia (sacro-iliacale gewrichten) en onder met het stuitbeen. Door de foramina sacralia treden de sacrale zenuwen uit. Het promontorium is een belangrijk oriëntatiepunt in de verloskunde.</p>","image_url":"","wiki_title":"Sacrum","match":"os sacrum|heiligbeen|sacrum","option_only":true},"os cuneiforme":{"title":"Os cuneiforme","short":"De ossa cuneiformia zijn drie wigvormige voetwortelbeentjes tussen het os naviculare en de eerste drie middenvoetsbeentjes.","definition":"<p>Er zijn drie <strong>ossa cuneiformia</strong> (mediale, intermediale en laterale). Door hun wigvorm helpen ze de dwarse voetboog te vormen. Ze articuleren met het os naviculare, met elkaar, met het os cuboideum en met de basis van metatarsale I–III (onderdeel van het gewricht van Lisfranc).</p>","image_url":"","wiki_title":"Cuneiform bones","match":"os cuneiforme|ossa cuneiformia|wigvormig been","option_only":true},"a. radialis":{"title":"A. radialis","short":"De a. radialis is een eindtak van de a. brachialis die aan de duimzijde van de onderarm naar de hand loopt; hier voel je de pols.","definition":"<p>De <strong>a. radialis</strong> loopt langs de radiale zijde van de onderarm en is bij de pols goed palpabel lateraal van de pees van de m. flexor carpi radialis. Ze loopt door de anatomische snuifdoos naar de handrug en vormt in de hand vooral de diepe handboog (arcus palmaris profundus). Ze wordt veel gebruikt voor arteriële bloedafname en voor hartkatheterisatie.</p>","image_url":"","wiki_title":"Radial artery","match":"a. radialis|arteria radialis","option_only":true},"a. femoralis":{"title":"A. femoralis","short":"De a. femoralis is de grote slagader van het bovenbeen, de voortzetting van de a. iliaca externa onder het ligamentum inguinale.","definition":"<p>De <strong>a. femoralis</strong> loopt vanaf het ligamentum inguinale door de trigonum femorale, lateraal van de v. femoralis en mediaal van de n. femoralis. In de lies is de pols goed voelbaar. Ze geeft de a. profunda femoris af en loopt verder door het kanaal van Hunter, waarna ze in de knieholte a. poplitea heet. Ze wordt gebruikt als toegang voor katheterisaties.</p>","image_url":"","wiki_title":"Femoral artery","match":"a. femoralis|arteria femoralis","option_only":true},"a. iliaca interna":{"title":"A. iliaca interna","short":"De a. iliaca interna voorziet de bekkenorganen, de bilspieren en het perineum van bloed.","definition":"<p>De <strong>a. iliaca interna</strong> ontstaat uit de a. iliaca communis en loopt het kleine bekken in. Ze heeft een voorste en achterste stam, met takken naar blaas, uterus (a. uterina), rectum, bilspieren (aa. gluteae) en perineum (a. pudenda interna). Bij de foetus lopen de navelarteriën vanuit deze arterie naar de placenta.</p>","image_url":"","wiki_title":"Internal iliac artery","match":"a. iliaca interna|arteria iliaca interna|a. hypogastrica","option_only":true},"n. ischiadicus":{"title":"N. ischiadicus","short":"De n. ischiadicus (L4–S3) is de dikste zenuw van het lichaam en innerveert de hamstrings en alle spieren onder de knie.","definition":"<p>De <strong>n. ischiadicus</strong> verlaat het bekken via het foramen ischiadicum majus, meestal onder de m. piriformis, en loopt aan de achterzijde van het bovenbeen. Boven de knieholte splitst hij in de n. tibialis en de n. fibularis communis. Hij is kwetsbaar bij een intramusculaire injectie in het verkeerde kwadrant van de bil en bij een posterieure heupluxatie.</p>","image_url":"","wiki_title":"Sciatic nerve","match":"n. ischiadicus|nervus ischiadicus|heupzenuw","option_only":true},"n. cutaneus antebrachii medialis":{"title":"N. cutaneus antebrachii medialis","short":"De n. cutaneus antebrachii medialis is een sensibele zenuw uit de fasciculus medialis voor de huid van de mediale onderarm.","definition":"<p>De <strong>n. cutaneus antebrachii medialis</strong> (C8–T1) komt rechtstreeks uit de fasciculus medialis van de plexus brachialis. Hij loopt met de v. basilica mee en verzorgt de huid aan de mediale (ulnaire) zijde van de onderarm tot de pols. Het is een zuiver sensibele zenuw.</p>","image_url":"","wiki_title":"Medial cutaneous nerve of forearm","match":"n. cutaneus antebrachii medialis","option_only":true},"oedeem":{"title":"Oedeem","short":"Oedeem is een ophoping van vocht in het interstitium, bijvoorbeeld als zwelling van enkels of onderbenen.","definition":"<p><strong>Oedeem</strong> ontstaat volgens de wetten van Starling door een verhoogde hydrostatische druk (hartfalen, veneuze insufficiëntie, overvulling), een verlaagde colloïd-osmotische druk (laag albumine bij nefrotisch syndroom, leverziekte, ondervoeding), een verhoogde vaatpermeabiliteit (ontsteking, allergie) of een verminderde lymfeafvoer (lymfoedeem). Putjesvormend oedeem blijft na indrukken even zichtbaar.</p>","image_url":"","wiki_title":"Edema","match":"oedeem|vochtophoping","option_only":true},"mri":{"title":"MRI","short":"MRI maakt met een sterk magneetveld en radiogolven gedetailleerde beelden van weke delen, zonder ioniserende straling.","definition":"<p>Bij <strong>MRI</strong> worden waterstofkernen in een sterk magneetveld door radiogolven aangeslagen; het signaal bij terugkeer verschilt per weefseltype. MRI is bijzonder geschikt voor hersenen, ruggenmerg, gewrichten, weke delen en het bekken. Nadelen zijn de lange duur, kosten en beperkingen bij pacemakers en sommige metalen implantaten.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri|mri-scan|magnetic resonance imaging","option_only":true},"reumatoïde artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoïde artritis|reumatoide artritis|reumatoïde arthritis","option_only":true},"jicht":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jicht|arthritis urica|podagra","option_only":true},"osteoporose":{"title":"Osteoporose","short":"Osteoporose is een verlaagde botmassa met verzwakte botstructuur, waardoor botten sneller breken.","definition":"<p>Bij <strong>osteoporose</strong> is de afbraak van bot groter dan de opbouw. Risicofactoren: hoge leeftijd, postmenopauzaal oestrogeentekort, corticosteroïden, laag lichaamsgewicht, roken, alcohol en weinig beweging. Typische fracturen zijn wervelinzakkingen, heupfracturen en distale radiusfracturen. Diagnose met een DEXA-scan (T-score ≤ −2,5); behandeling o.a. met bisfosfonaten, calcium en vitamine D.</p>","image_url":"","wiki_title":"Osteoporosis","match":"osteoporose|botontkalking","option_only":true},"osteomyelitis":{"title":"Osteomyelitis","short":"Osteomyelitis is een infectie van het bot, meestal door Staphylococcus aureus.","definition":"<p><strong>Osteomyelitis</strong> ontstaat via de bloedbaan (vooral bij kinderen in de metafysen van lange pijpbeenderen), vanuit een nabijgelegen infectie (bijv. diabetische voet, decubitus) of na een open fractuur of operatie. Klachten: pijn, koorts, zwelling. Diagnose met MRI en kweek (bot of bloed). Chronische osteomyelitis met dood bot (sequester) vergt vaak chirurgie naast langdurige antibiotica.</p>","image_url":"","wiki_title":"Osteomyelitis","match":"osteomyelitis|botontsteking","option_only":true},"lactaat dehydrogenase (ld)":{"title":"Lactaatdehydrogenase (LDH)","short":"LDH is een enzym in vrijwel alle cellen dat pyruvaat en lactaat in elkaar omzet; een verhoogde bloedwaarde wijst op celschade.","definition":"<p><strong>Lactaatdehydrogenase</strong> zet pyruvaat om in lactaat (en omgekeerd) en regenereert daarbij NAD⁺, wat anaerobe glycolyse mogelijk maakt. In het bloed is LDH een aspecifieke marker van weefselschade: het is verhoogd bij hemolyse, myocardinfarct, leverschade, spierschade en snelgroeiende tumoren zoals lymfomen.</p>","image_url":"","wiki_title":"Lactate dehydrogenase","match":"lactaat dehydrogenase (ld)|lactaatdehydrogenase|ldh|ld","option_only":true},"achondroplasie":{"title":"Achondroplasie","short":"Achondroplasie is de meest voorkomende vorm van disproportionele dwerggroei, door een activerende mutatie in FGFR3.","definition":"<p>Bij <strong>achondroplasie</strong> remt het overactieve FGFR3 de enchondrale verbening in de groeischijven. Kenmerken: korte ledematen (vooral bovenarmen en bovenbenen), een relatief normale romp, een groot hoofd met een prominent voorhoofd en een normale intelligentie. Het erft autosomaal dominant over, maar ontstaat meestal de novo (vaak bij oudere vaders).</p>","image_url":"","wiki_title":"Achondroplasia","match":"achondroplasie","option_only":true},"carpaal tunnel syndroom":{"title":"Carpaletunnelsyndroom","short":"Bij het carpaletunnelsyndroom is de n. medianus bekneld in de carpale tunnel, met tintelingen in duim, wijs- en middelvinger.","definition":"<p>Het <strong>carpaletunnelsyndroom</strong> is de meest voorkomende zenuwbeknelling. Klachten: tintelingen en doofheid in het gebied van de n. medianus, vaak ’s nachts, verbeterend door schudden met de hand; later zwakte en atrofie van de duimmuis. Risicofactoren zijn zwangerschap, diabetes, hypothyreoïdie, reumatoïde artritis en repetitieve bewegingen. Behandeling met spalk, injectie of klieving van het lig. carpi transversum.</p>","image_url":"","wiki_title":"Carpal tunnel syndrome","match":"carpaal tunnel syndroom|carpaletunnelsyndroom|cts","option_only":true},"n. medianus":{"title":"N. medianus","short":"De n. medianus (C6–T1) loopt door de carpale tunnel en innerveert o.a. de duimmuis en het gevoel van duim, wijs- en middelvinger.","definition":"<p>De <strong>n. medianus</strong> ontstaat uit de fasciculus lateralis en medialis van de plexus brachialis. Hij innerveert de meeste flexoren van de onderarm, de spieren van de duimmuis en de laterale mm. lumbricales, en sensibel de palmaire zijde van duim, wijs-, middel- en de radiale helft van de ringvinger. Bij een hoog letsel ontstaat een ‘eedhand’.</p>","image_url":"","wiki_title":"Median nerve","match":"n. medianus|nervus medianus","option_only":true},"n. thoracicus longus":{"title":"N. thoracicus longus","short":"De n. thoracicus longus (C5–C7) innerveert de m. serratus anterior.","definition":"<p>De <strong>n. thoracicus longus</strong> loopt over de laterale borstwand naar beneden, oppervlakkig op de m. serratus anterior. Daardoor is hij kwetsbaar bij okselklierdissectie, trauma en zware belasting van de schouder. Uitval geeft een scapula alata, vooral zichtbaar bij duwen tegen een muur.</p>","image_url":"","wiki_title":"Long thoracic nerve","match":"n. thoracicus longus|nervus thoracicus longus","option_only":true},"os scaphoideum":{"title":"Os scaphoideum","short":"Het os scaphoideum is het bootvormige handwortelbeentje aan de duimzijde van de proximale rij.","definition":"<p>Het <strong>os scaphoideum</strong> overbrugt de proximale en distale handwortelrij en breekt vaak na een val op de uitgestrekte hand. Omdat de bloedvoorziening van distaal naar proximaal loopt, kan het proximale fragment na een fractuur afsterven (avasculaire necrose) en ontstaat gemakkelijk een pseudartrose. Een fractuur is op de eerste foto soms niet zichtbaar.</p>","image_url":"","wiki_title":"Scaphoid bone","match":"os scaphoideum|scafoïd|naviculare van de hand","option_only":true},"scharniergewricht":{"title":"Scharniergewricht","short":"Een scharniergewricht laat beweging om één as toe: flexie en extensie.","definition":"<p>Een <strong>scharniergewricht</strong> (ginglymus) is een eenassig gewricht, vergelijkbaar met een deurscharnier. Sterke collaterale banden voorkomen zijwaartse beweging. Voorbeelden zijn de interfalangeale gewrichten van vingers en tenen en het bovenste spronggewricht.</p>","image_url":"","wiki_title":"Hinge joint","match":"scharniergewricht|ginglymus","option_only":true},"inversie":{"title":"Inversie (voet)","short":"Inversie is het kantelen van de voetzool naar binnen (mediaal); de tegenovergestelde beweging is eversie.","definition":"<p><strong>Inversie</strong> vindt vooral plaats in het onderste spronggewricht (subtalair) en de gewrichten van de middenvoet. Ze maakt deel uit van supinatie (inversie, adductie en plantairflexie). Een inversietrauma (omslaan van de enkel) belast vooral de laterale enkelbanden.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"inversie","option_only":true},"concentrische contractie":{"title":"Concentrische contractie","short":"Bij een concentrische contractie verkort de spier terwijl hij kracht levert, bijvoorbeeld de biceps bij het optillen van een gewicht.","definition":"<p>Bij <strong>concentrische</strong> spierarbeid is de spierkracht groter dan de externe belasting en verkort de spier. Bij <em>excentrische</em> arbeid verlengt de spier onder spanning (bijv. remmend bij het neerzetten van een gewicht); dat geeft de meeste spierpijn. Bij <em>isometrische</em> arbeid blijft de lengte gelijk.</p>","image_url":"","wiki_title":"Muscle contraction","match":"concentrische contractie|concentrische spierwerking","option_only":true},"isometrische contracie":{"title":"Isometrische contractie","short":"Bij een isometrische contractie ontwikkelt de spier kracht zonder van lengte te veranderen, bijvoorbeeld bij het vasthouden van een houding.","definition":"<p>Bij <strong>isometrische</strong> spierarbeid is de spierkracht even groot als de externe belasting, zodat er geen beweging ontstaat. Voorbeelden zijn duwen tegen een muur of een houding vasthouden. Het geeft een flinke stijging van de bloeddruk.</p>","image_url":"","wiki_title":"Muscle contraction","match":"isometrische contracie|isometrische contractie|isometrische spierwerking","option_only":true},"tibiafractuur":{"title":"Tibiafractuur","short":"Een tibiafractuur is een breuk van het scheenbeen, vaak door hoog-energetisch trauma.","definition":"<p>Omdat de voorzijde van de tibia direct onder de huid ligt, zijn <strong>tibiafracturen</strong> relatief vaak open. Ze hebben een verhoogd risico op een compartimentsyndroom (toenemende pijn, vooral bij passief rekken) en vertraagde genezing door de beperkte bekleding met weke delen.</p>","image_url":"","wiki_title":"Tibial fracture","match":"tibiafractuur|scheenbeenbreuk","option_only":true},"bse":{"title":"Bezinkingssnelheid (BSE)","short":"De BSE meet hoe snel rode bloedcellen in een buisje uitzakken; een verhoogde waarde wijst op ontsteking, maar is weinig specifiek.","definition":"<p>De <strong>bezinkingssnelheid</strong> stijgt doordat acutefase-eiwitten (vooral fibrinogeen) en immunoglobulinen de rode bloedcellen in rouleaux laten samenklonteren. Ze stijgt en daalt trager dan het CRP. Sterk verhoogde waarden passen bij o.a. reuscelarteriitis, polymyalgia reumatica, multipel myeloom en ernstige infecties. Leeftijd, geslacht en anemie beïnvloeden de waarde.</p>","image_url":"","wiki_title":"Erythrocyte sedimentation rate","match":"bse|bezinking|bezinkingssnelheid|erytrocytenbezinking","option_only":true},"zoutzuur":{"title":"Zoutzuur (maagzuur)","short":"Zoutzuur wordt door de pariëtale cellen van de maag uitgescheiden; het maakt de maaginhoud zuur, doodt micro-organismen en activeert pepsine.","definition":"<p>De pariëtale cellen pompen H⁺ via de H⁺/K⁺-ATPase het maaglumen in; chloride volgt. Stimulatoren zijn gastrine, histamine (H2) en acetylcholine (vagus); somatostatine remt. Het lage pH (1–2) helpt bij eiwitvertering en ijzeropname en beschermt tegen infecties. Protonpompremmers en H2-antagonisten verminderen de productie.</p>","image_url":"","wiki_title":"Gastric acid","match":"zoutzuur|hcl|maagzuur","option_only":true},"supinatie":{"title":"Supinatie","short":"Supinatie is het naar boven of voren draaien van de handpalm (onderarm) of het kantelen van de voetzool naar binnen.","definition":"<p>In de <strong>onderarm</strong> draait de radius bij supinatie parallel naast de ulna, zodat de handpalm naar voren (of boven) wijst; belangrijke supinatoren zijn de m. biceps brachii en m. supinator. Bij de <strong>voet</strong> is supinatie een gecombineerde beweging van inversie, adductie en plantairflexie.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"supinatie","option_only":true},"pronatie":{"title":"Pronatie","short":"Pronatie is het naar beneden of achteren draaien van de handpalm, of het kantelen van de voetzool naar buiten.","definition":"<p>In de <strong>onderarm</strong> kruist de radius bij pronatie over de ulna; belangrijke pronatoren zijn de m. pronator teres en m. pronator quadratus. Bij de <strong>voet</strong> is pronatie een combinatie van eversie, abductie en dorsaalflexie.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"pronatie","option_only":true},"eversie":{"title":"Eversie","short":"Eversie is het kantelen van de voetzool naar buiten (lateraal); de tegenovergestelde beweging is inversie.","definition":"<p><strong>Eversie</strong> vindt vooral plaats in het onderste spronggewricht en de gewrichten van de middenvoet. De belangrijkste everroren zijn de mm. fibulares (peronei) longus en brevis, geïnnerveerd door de n. fibularis superficialis.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"eversie","option_only":true},"abductie":{"title":"Abductie","short":"Abductie is een beweging van een lichaamsdeel van de middellijn af, bijvoorbeeld de arm zijwaarts heffen.","definition":"<p>Bij <strong>abductie</strong> beweegt een ledemaat in het frontale vlak weg van het lichaam (bij vingers en tenen: weg van de as van de hand of voet). Het tegenovergestelde is adductie. Voorbeelden van abductoren zijn de m. deltoideus en m. supraspinatus (schouder) en de m. gluteus medius en minimus (heup).</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"abductie","option_only":true},"exorotatie":{"title":"Exorotatie","short":"Exorotatie is draaien van een ledemaat om de lengteas naar buiten (lateraal).","definition":"<p>Bij <strong>exorotatie</strong> draait de voorzijde van bijv. de bovenarm of het bovenbeen naar buiten. In de schouder zijn de m. infraspinatus en m. teres minor de belangrijkste exorotatoren. Bij een frozen shoulder is de exorotatie vaak als eerste en het meest beperkt.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"exorotatie|externe rotatie|buitenwaartse rotatie","option_only":true},"dorsaalflexie":{"title":"Dorsaalflexie","short":"Dorsaalflexie is het optrekken van de voet (of het naar achteren buigen van de hand) richting de rugzijde.","definition":"<p>Bij de enkel betekent <strong>dorsaalflexie</strong> dat de voetrug richting het scheenbeen beweegt; de m. tibialis anterior is de belangrijkste spier (n. fibularis profundus). Uitval geeft een klapvoet. Bij de pols betekent dorsaalflexie extensie van de hand.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"dorsaalflexie|dorsiflexie","option_only":true},"plantairflexie":{"title":"Plantairflexie","short":"Plantairflexie is het naar beneden buigen van de voet, zoals bij op de tenen staan.","definition":"<p>De belangrijkste <strong>plantairflexoren</strong> zijn de m. gastrocnemius en m. soleus (samen de m. triceps surae, via de achillespees), geïnnerveerd door de n. tibialis. Bij een achillespeesruptuur is de plantairflexie verzwakt en is de test van Thompson positief.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"plantairflexie","option_only":true},"flexie":{"title":"Flexie","short":"Flexie is buigen: de hoek tussen twee lichaamsdelen wordt kleiner.","definition":"<p>Bij <strong>flexie</strong> beweegt een lichaamsdeel meestal naar voren in het sagittale vlak (bijv. de elleboog of heup buigen). Bij knie en enkel zijn er afwijkende afspraken (kniebuiging gaat naar achteren; bij de enkel spreekt men van dorsaal- en plantairflexie). Het tegenovergestelde is extensie.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"flexie|buiging","option_only":true},"extensie":{"title":"Extensie","short":"Extensie is strekken: de hoek tussen twee lichaamsdelen wordt groter.","definition":"<p><strong>Extensie</strong> is de tegenbeweging van flexie, bijvoorbeeld het strekken van elleboog of knie. Voorbij de neutrale stand spreekt men van hyperextensie (bijv. van de rug of de pols).</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"extensie|strekking","option_only":true},"n. obturatorius":{"title":"N. obturatorius","short":"De n. obturatorius (L2–L4) innerveert de adductoren van het bovenbeen en de huid aan de binnenkant van de dij.","definition":"<p>De <strong>n. obturatorius</strong> komt uit de plexus lumbalis, loopt langs de bekkenwand en verlaat het bekken via het canalis obturatorius. Hij innerveert de mediale (adductoren)loge. Letsel kan ontstaan bij bekkenchirurgie, bekkenfracturen of bevallingen, met zwakte bij adductie en gevoelsstoornissen aan de binnenzijde van de dij.</p>","image_url":"","wiki_title":"Obturator nerve","match":"n. obturatorius|nervus obturatorius","option_only":true},"n. femoralis":{"title":"N. femoralis","short":"De n. femoralis (L2–L4) innerveert de m. quadriceps en m. iliopsoas en de huid aan de voorkant van de dij en binnenkant van het onderbeen.","definition":"<p>De <strong>n. femoralis</strong> loopt langs de m. psoas en onder het lig. inguinale door, lateraal van de a. femoralis. Hij is nodig voor kniestrekking en de kniepeesreflex. Zijn sensibele eindtak, de n. saphenus, verzorgt de mediale zijde van het onderbeen. Uitval geeft een zwakke kniestrekking en een afwezige kniepeesreflex.</p>","image_url":"","wiki_title":"Femoral nerve","match":"n. femoralis|nervus femoralis","option_only":true},"a. iliaca externa":{"title":"A. iliaca externa","short":"De a. iliaca externa loopt van de splitsing van de a. iliaca communis naar het lig. inguinale, waar ze a. femoralis gaat heten.","definition":"<p>De <strong>a. iliaca externa</strong> loopt langs de m. psoas en geeft vlak boven het lig. inguinale de a. epigastrica inferior en de a. circumflexa ilium profunda af. Bij een niertransplantatie wordt de donornier vaak op deze arterie aangesloten.</p>","image_url":"","wiki_title":"External iliac artery","match":"a. iliaca externa|arteria iliaca externa","option_only":true},"a. poplitea":{"title":"A. poplitea","short":"De a. poplitea is de voortzetting van de a. femoralis in de knieholte; ze splitst in de a. tibialis anterior en de truncus tibiofibularis.","definition":"<p>De <strong>a. poplitea</strong> ligt diep in de knieholte, vlak tegen het kniekapsel, en is daardoor kwetsbaar bij een knieluxatie. De pols is moeilijk te voelen. Er kan een popliteaal aneurysma ontstaan, dat vaak dubbelzijdig is en embolieën naar het onderbeen kan geven.</p>","image_url":"","wiki_title":"Popliteal artery","match":"a. poplitea|arteria poplitea|knieholteslagader","option_only":true},"humerus":{"title":"Humerus (opperarmbeen)","short":"De humerus is het bot van de bovenarm, tussen schouder en elleboog.","definition":"<p>De <strong>humerus</strong> heeft proximaal de kop, het collum anatomicum, de tubercula en het collum chirurgicum; langs de schacht loopt de n. radialis in een groeve; distaal liggen de epicondylen, de trochlea en het capitulum. Fracturen van het collum chirurgicum bedreigen de n. axillaris, schachtfracturen de n. radialis.</p>","image_url":"","wiki_title":"Humerus","match":"humerus|opperarmbeen","option_only":true},"patella":{"title":"Patella (knieschijf)","short":"De patella is het grootste sesambeen van het lichaam, in de pees van de m. quadriceps.","definition":"<p>De <strong>patella</strong> vergroot de hefboomwerking van de m. quadriceps bij kniestrekking en beschermt het kniegewricht. Ze glijdt in de groeve van de femur (trochlea). Patella-luxatie gebeurt meestal naar lateraal, vooral bij jonge vrouwen met losse banden of een afwijkende stand.</p>","image_url":"","wiki_title":"Patella","match":"patella|knieschijf","option_only":true},"olecranon":{"title":"Olecranon","short":"Het olecranon is het proximale uitsteeksel van de ulna dat de punt van de elleboog vormt.","definition":"<p>Het <strong>olecranon</strong> is de aanhechting van de m. triceps brachii en past bij strekking in de fossa olecrani van de humerus. Omdat het direct onder de huid ligt, is het kwetsbaar bij direct trauma; de bursa olecrani erboven kan ontsteken.</p>","image_url":"","wiki_title":"Olecranon","match":"olecranon","option_only":true},"os pubis":{"title":"Os pubis (schaambeen)","short":"Het os pubis is het voorste deel van het heupbeen; beide schaambeenderen zijn in de symfyse met elkaar verbonden.","definition":"<p>Het <strong>os pubis</strong> vormt samen met het os ilium en os ischii het heupbeen (os coxae), dat in het acetabulum samenkomt. De ramus superior en inferior begrenzen het foramen obturatum. Fracturen van de schaambeentakken komen veel voor bij ouderen na een val.</p>","image_url":"","wiki_title":"Pubis (bone)","match":"os pubis|schaambeen","option_only":true},"os cuboideum":{"title":"Os cuboideum","short":"Het os cuboideum is een voetwortelbeentje aan de laterale zijde van de voet, tussen calcaneus en de vierde en vijfde middenvoetsbeentjes.","definition":"<p>Het <strong>os cuboideum</strong> heeft aan de onderzijde een groeve waar de pees van de m. fibularis longus doorheen loopt. Het maakt deel uit van de laterale voetboog en van het gewricht van Chopart.</p>","image_url":"","wiki_title":"Cuboid bone","match":"os cuboideum|kubusvormig been","option_only":true},"os trapezoideum":{"title":"Os trapezoideum","short":"Het os trapezoideum is een klein handwortelbeentje in de distale rij, dat articuleert met het tweede middenhandsbeentje.","definition":"<p>Het <strong>os trapezoideum</strong> ligt tussen het os trapezium (aan de duimzijde) en het os capitatum. Het is het kleinste bot van de distale rij en breekt zelden.</p>","image_url":"","wiki_title":"Trapezoid bone","match":"os trapezoideum","option_only":true},"articulatio humeri":{"title":"Schoudergewricht (articulatio humeri)","short":"Het schoudergewricht is een kogelgewricht tussen de humeruskop en de ondiepe cavitas glenoidalis van de scapula.","definition":"<p>De <strong>articulatio humeri</strong> is het meest beweeglijke gewricht van het lichaam, maar ook het minst stabiel. Stabiliteit komt vooral van de rotatorcuff, het labrum en het kapsel met de glenohumerale banden. Luxaties gebeuren meestal naar voren (anterieur).</p>","image_url":"","wiki_title":"Shoulder joint","match":"articulatio humeri|glenohumeraal gewricht|schoudergewricht","option_only":true},"articulio radiocarpalis":{"title":"Radiocarpaal gewricht","short":"Het radiocarpale gewricht is het polsgewricht tussen de distale radius (met discus) en de proximale handwortelrij.","definition":"<p>De <strong>articulatio radiocarpalis</strong> is een ellipsoïd gewricht tussen de radius en het os scaphoideum, lunatum en (via de discus articularis) triquetrum. Het maakt flexie, extensie en radiaal- en ulnairdeviatie mogelijk; pro- en supinatie gebeuren in de radio-ulnaire gewrichten.</p>","image_url":"","wiki_title":"Wrist","match":"articulio radiocarpalis|articulatio radiocarpalis|radiocarpaal gewricht","option_only":true},"articulationes subtalaris en talocalcaneonavicularis":{"title":"Onderste spronggewricht","short":"Het onderste spronggewricht bestaat uit de verbinding tussen talus en calcaneus en tussen talus, calcaneus en naviculare; het maakt inversie en eversie mogelijk.","definition":"<p>Het <strong>onderste spronggewricht</strong> zorgt dat de voet zich kan aanpassen aan oneffen ondergrond, door inversie en eversie. Het bovenste spronggewricht (talocrurale gewricht) daarentegen maakt vooral dorsaal- en plantairflexie mogelijk.</p>","image_url":"","wiki_title":"Subtalar joint","match":"articulationes subtalaris en talocalcaneonavicularis|onderste spronggewricht|subtalair gewricht","option_only":true},"schouderluxatie":{"title":"Schouderluxatie","short":"Bij een schouderluxatie schiet de humeruskop uit de kom, meestal naar voren-onder.","definition":"<p>Bij een <strong>anterieure schouderluxatie</strong> (verreweg het meest voorkomend) staat de arm in lichte abductie en exorotatie, met een afgeplatte schouderronding en een leeg gevoel onder het acromion. Controleer altijd de n. axillaris (gevoel op de schouder). Bij jongeren is recidief luxeren vaak; bij ouderen komen cuffscheuren voor. Posterieure luxaties komen voor bij epileptische aanvallen en elektrocutie.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"schouderluxatie|luxatie van de schouder","option_only":true},"het beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"het beenmerg","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"lig. deltoideum":{"title":"Ligamentum deltoideum","short":"Het ligamentum deltoideum is de sterke, waaiervormige band aan de binnenzijde van de enkel.","definition":"<p>Het <strong>lig. deltoideum</strong> loopt van de malleolus medialis naar os naviculare, talus en calcaneus en heeft een oppervlakkige en een diepe laag. Het is veel sterker dan de laterale enkelbanden en stabiliseert de enkel aan de mediale zijde.</p>","image_url":"","wiki_title":"Deltoid ligament","match":"lig. deltoideum|ligamentum deltoideum|mediale enkelband","option_only":true},"lig. calcaneofibulare":{"title":"Ligamentum calcaneofibulare","short":"Het ligamentum calcaneofibulare is een laterale enkelband van de malleolus lateralis naar de calcaneus.","definition":"<p>Het <strong>lig. calcaneofibulare</strong> vormt met het lig. talofibulare anterius en posterius het laterale bandcomplex van de enkel en overspant zowel het bovenste als het onderste spronggewricht.</p>","image_url":"","wiki_title":"Calcaneofibular ligament","match":"lig. calcaneofibulare|ligamentum calcaneofibulare","option_only":true},"artritis psoriatica":{"title":"Artritis psoriatica","short":"Artritis psoriatica is een gewrichtsontsteking bij psoriasis, met o.a. DIP-artritis, dactylitis, enthesitis en nagelafwijkingen.","definition":"<p><strong>Artritis psoriatica</strong> kan zich uiten als oligoartritis, polyartritis (lijkend op RA), DIP-artritis, axiale betrokkenheid of het zeldzame arthritis mutilans. Typisch zijn worstvingers (dactylitis), enthesitis en nagelpsoriasis. Reumafactor is meestal negatief.</p>","image_url":"","wiki_title":"Psoriatic arthritis","match":"artritis psoriatica|arthritis psoriatica","option_only":true},"wervelfractuur":{"title":"Wervelfractuur","short":"Een wervelfractuur is een breuk van een wervel; bij ouderen vaak een inzakking door osteoporose.","definition":"<p><strong>Osteoporotische wervelfracturen</strong> ontstaan vaak bij gering trauma of spontaan, vooral in de borst- en lendenwervelkolom, en geven acute rugpijn, lengteverlies en een toenemende kyfose. Na hoogenergetisch trauma kunnen wervelfracturen instabiel zijn en het ruggenmerg bedreigen. Een wervelinzakking bij een jonger persoon zonder trauma vraagt om onderzoek naar o.a. metastasen of myeloom.</p>","image_url":"","wiki_title":"Vertebral compression fracture","match":"wervelfractuur|wervelinzakking|inzakkingsfractuur","option_only":true},"artrose heup":{"title":"Coxartrose (heupartrose)","short":"Coxartrose is slijtage van het heupgewricht, met pijn in lies of bil en een beperkte (vooral endo)rotatie.","definition":"<p>Bij <strong>coxartrose</strong> geeft het kraakbeenverlies startpijn, pijn bij belasting en een beperking van de bewegingen, het eerst van endorotatie en flexie. De pijn wordt vaak in de lies gevoeld en kan uitstralen naar de knie. Behandeling begint met oefentherapie, gewichtsverlies en pijnstilling; bij ernstige klachten volgt een totale heupprothese.</p>","image_url":"","wiki_title":"Hip osteoarthritis","match":"artrose heup|coxartrose|heupartrose","option_only":true},"artrose van de knie":{"title":"Gonartrose (knieartrose)","short":"Gonartrose is slijtage van het kniegewricht, met pijn bij belasting, stijfheid en soms zwelling.","definition":"<p><strong>Gonartrose</strong> treft vaak eerst het mediale compartiment. Risicofactoren: leeftijd, overgewicht, eerder letsel (meniscus, voorste kruisband) en standafwijkingen. Op de röntgenfoto zijn gewrichtsspleetversmalling en osteofyten te zien. Behandeling: oefenen, afvallen, pijnstilling, eventueel een injectie; in een later stadium een knieprothese of osteotomie.</p>","image_url":"","wiki_title":"Knee osteoarthritis","match":"artrose van de knie|gonartrose|knieartrose","option_only":true},"hla-b27":{"title":"HLA-B27","short":"HLA-B27 is een MHC klasse I-variant die sterk geassocieerd is met spondyloartritiden zoals de ziekte van Bechterew.","definition":"<p>Dragers van <strong>HLA-B27</strong> hebben een sterk verhoogd risico op axiale spondyloartritis, reactieve artritis, uveïtis anterior en artritis bij IBD of psoriasis. Toch krijgt de grote meerderheid van de dragers nooit een van deze ziekten, en een deel van de patiënten is HLA-B27-negatief: de test ondersteunt de diagnose, maar bewijst haar niet.</p>","image_url":"","wiki_title":"HLA-B27","match":"hla-b27|hla b27|aanwezigheid van hla b27 antigeen","option_only":true},"urinezuur":{"title":"Urinezuur","short":"Urinezuur is het eindproduct van de purineafbraak; een te hoge spiegel kan leiden tot jicht en nierstenen.","definition":"<p><strong>Urinezuur</strong> wordt gevormd door xanthineoxidase en vooral via de nier uitgescheiden. Hyperurikemie ontstaat door verminderde uitscheiding (nierfunctiestoornis, diuretica, alcohol) of verhoogde aanmaak (celafbraak bij chemotherapie, purinerijk voedsel). Uraatkristallen veroorzaken jicht; allopurinol remt de vorming van urinezuur.</p>","image_url":"","wiki_title":"Uric acid","match":"urinezuur|uraat|hyperurikemie","option_only":true},"a. tibialis anterior":{"title":"A. tibialis anterior","short":"De a. tibialis anterior voorziet de voorste loge van het onderbeen en gaat over in de a. dorsalis pedis op de voetrug.","definition":"<p>De <strong>a. tibialis anterior</strong> ontstaat uit de a. poplitea, gaat door de membrana interossea naar voren en loopt samen met de n. fibularis profundus. Op de voetrug, lateraal van de pees van de m. extensor hallucis longus, is de a. dorsalis pedis voelbaar.</p>","image_url":"","wiki_title":"Anterior tibial artery","match":"a. tibialis anterior|arteria tibialis anterior","option_only":true},"a. profunda brachii":{"title":"A. profunda brachii","short":"De a. profunda brachii is de diepe tak van de a. brachialis die met de n. radialis om de achterzijde van de humerus loopt.","definition":"<p>De <strong>a. profunda brachii</strong> voorziet vooral de m. triceps brachii en loopt met de n. radialis door de sulcus nervi radialis. Bij een fractuur van de humerusschacht kunnen zenuw en arterie samen beschadigd raken.</p>","image_url":"","wiki_title":"Deep artery of arm","match":"a. profunda brachii|arteria profunda brachii","option_only":true},"vezelig kraakbeen":{"title":"Vezelig kraakbeen","short":"Vezelig kraakbeen bevat veel collageen type I-vezels en is zeer bestand tegen druk en trek; het zit o.a. in tussenwervelschijven, menisci en de symfyse.","definition":"<p><strong>Vezelig kraakbeen</strong> bestaat uit rijen chondrocyten tussen dikke bundels collageen type I. Het heeft geen perichondrium. Het komt voor in de annulus fibrosus van tussenwervelschijven, de menisci van de knie, de symfysis pubica, de discus articularis van kaak en pols en bij peesaanhechtingen.</p>","image_url":"","wiki_title":"Fibrocartilage","match":"vezelig kraakbeen|fibrocartilago|fibreus kraakbeen","option_only":true},"spongieus bot":{"title":"Spongieus bot","short":"Spongieus bot bestaat uit een netwerk van botbalkjes (trabekels) met beenmerg ertussen; het zit in wervellichamen en de uiteinden van pijpbeenderen.","definition":"<p>De trabekels van <strong>spongieus bot</strong> volgen de belastingslijnen. Omdat het een groot oppervlak heeft, wordt het snel omgebouwd en is het gevoelig voor osteoporose; daardoor ontstaan fracturen vaak in wervels, het collum femoris en de distale radius. Tussen de trabekels ligt rood beenmerg.</p>","image_url":"","wiki_title":"Cancellous bone","match":"spongieus bot|trabeculair bot|sponsachtig bot","option_only":true},"glycosaminoglycanen":{"title":"Glycosaminoglycanen","short":"Glycosaminoglycanen zijn lange, negatief geladen suikerketens in de extracellulaire matrix die veel water binden.","definition":"<p><strong>Glycosaminoglycanen</strong> bestaan uit herhaalde disacharide-eenheden en zijn (behalve hyaluronzuur) gesulfateerd en aan een kerneiwit gebonden als proteoglycaan. Voorbeelden: chondroïtinesulfaat, keratansulfaat, heparansulfaat, dermatansulfaat en heparine. Door hun lading trekken ze water aan en vormen ze een drukbestendige gel. Afbraakstoornissen geven mucopolysacharidosen.</p>","image_url":"","wiki_title":"Glycosaminoglycan","match":"glycosaminoglycanen|gag's|mucopolysachariden","option_only":true},"extracellulaire grondsubstantie":{"title":"Grondsubstantie","short":"De grondsubstantie is het amorfe, gelachtige deel van de extracellulaire matrix tussen cellen en vezels.","definition":"<p><strong>Grondsubstantie</strong> bestaat uit water, glycosaminoglycanen, proteoglycanen en adhesieve glycoproteïnen (zoals fibronectine en laminine). Ze vult de ruimte, laat diffusie van voedingsstoffen toe en bepaalt samen met de vezels de mechanische eigenschappen van bindweefsel.</p>","image_url":"","wiki_title":"Ground substance","match":"extracellulaire grondsubstantie|grondsubstantie","option_only":true},"mucoïd bindweefsel":{"title":"Mucoïd bindweefsel (gelei van Wharton)","short":"Mucoïd bindweefsel is gelachtig embryonaal bindweefsel met veel grondsubstantie; het vormt de gelei van Wharton in de navelstreng.","definition":"<p><strong>Mucoïd bindweefsel</strong> bevat weinig vezels en verspreide fibroblasten in een grondsubstantie rijk aan hyaluronzuur. In de navelstreng beschermt het de vaten tegen dichtdrukken en knikken.</p>","image_url":"","wiki_title":"Wharton's jelly","match":"mucoïd bindweefsel|gelei van wharton|slijmweefsel","option_only":true},"univacuolair vetweefsel":{"title":"Wit (univacuolair) vetweefsel","short":"Wit vetweefsel bestaat uit vetcellen met één grote vetdruppel; het slaat energie op en maakt hormonen zoals leptine.","definition":"<p>In <strong>wit vetweefsel</strong> drukt één grote druppel triglyceriden de kern naar de rand (zegelringvorm). Het dient als energieopslag, isolatie en bescherming en maakt adipokinen zoals leptine en adiponectine. Bruin vetweefsel heeft juist veel kleine druppels en mitochondriën met UCP1 voor warmteproductie.</p>","image_url":"","wiki_title":"White adipose tissue","match":"univacuolair vetweefsel|wit vetweefsel|unilocular vetweefsel","option_only":true},"groeihormoon":{"title":"Groeihormoon (GH)","short":"Groeihormoon wordt door de hypofysevoorkwab gemaakt en stimuleert groei, vooral via IGF-1 uit de lever.","definition":"<p><strong>Groeihormoon</strong> wordt pulsatiel afgegeven, vooral in de diepe slaap, gestimuleerd door GHRH en geremd door somatostatine. Het stimuleert via IGF-1 de lengtegroei van botten en de eiwitsynthese, en werkt direct anti-insulinair (lipolyse, hogere glucose). Een tekort geeft groeiachterstand bij kinderen; een overmaat gigantisme (vóór sluiting van de groeischijven) of acromegalie.</p>","image_url":"","wiki_title":"Growth hormone","match":"groeihormoon|gh|somatotropine","option_only":true},"calcaneus":{"title":"Calcaneus (hielbeen)","short":"De calcaneus is het grootste voetwortelbeentje en vormt de hiel; de achillespees hecht erop aan.","definition":"<p>De <strong>calcaneus</strong> draagt het lichaamsgewicht naar de grond over en articuleert met de talus (onderste spronggewricht) en het os cuboideum. Het sustentaculum tali ondersteunt de talus. Bij een val van hoogte kan de calcaneus breken; bij hielpijn denkt men aan fasciitis plantaris of een achillespeesprobleem.</p>","image_url":"","wiki_title":"Calcaneus","match":"calcaneus|hielbeen","option_only":true},"talus":{"title":"Talus (sprongbeen)","short":"De talus is het voetwortelbeentje dat het onderbeen met de voet verbindt; er hechten geen spieren aan.","definition":"<p>De <strong>talus</strong> vormt met tibia en fibula het bovenste spronggewricht en met de calcaneus en het os naviculare het onderste spronggewricht. Het bot is grotendeels bedekt met kraakbeen en heeft een kwetsbare bloedvoorziening, waardoor een fractuur van de talushals tot avasculaire necrose kan leiden.</p>","image_url":"","wiki_title":"Talus bone","match":"talus|sprongbeen","option_only":true},"os naviculare":{"title":"Os naviculare (voet)","short":"Het os naviculare is het bootvormige voetwortelbeentje aan de mediale zijde, tussen talus en de ossa cuneiformia.","definition":"<p>Het <strong>os naviculare</strong> vormt de top van de mediale voetboog en is de aanhechting van de m. tibialis posterior. Een accessoir naviculare kan pijn geven. (In de hand wordt de term soms gebruikt voor het os scaphoideum.)</p>","image_url":"","wiki_title":"Navicular bone","match":"os naviculare|naviculare","option_only":true},"os ilium":{"title":"Os ilium (darmbeen)","short":"Het os ilium is het bovenste, waaiervormige deel van het heupbeen, met de crista iliaca.","definition":"<p>Het <strong>os ilium</strong> vormt samen met het os ischii en os pubis het heupbeen en draagt bij aan het acetabulum. Aan de crista iliaca hechten buikspieren aan; de spina iliaca anterior superior is een belangrijk oriëntatiepunt. De bekkenkam wordt gebruikt voor beenmergonderzoek en botgrafts.</p>","image_url":"","wiki_title":"Ilium (bone)","match":"os ilium|darmbeen|ilium","option_only":true},"caput ulnae":{"title":"Caput ulnae","short":"Het caput ulnae is het distale uiteinde (de kop) van de ulna, aan de pinkzijde van de pols.","definition":"<p>Het <strong>caput ulnae</strong> articuleert met de radius in het distale radio-ulnaire gewricht en draagt via de discus articularis (TFCC) bij aan het polsgewricht. Het is aan de dorsale-ulnaire zijde van de pols voelbaar. Bij reumatoïde artritis kan het opvallend prominent worden.</p>","image_url":"","wiki_title":"Ulna","match":"caput ulnae|ulnakop","option_only":true},"articulatio radio-ulnaris distalis":{"title":"Distaal radio-ulnair gewricht","short":"Het distale radio-ulnaire gewricht is een draaigewricht tussen radius en ulnakop, nodig voor pro- en supinatie.","definition":"<p>In het <strong>distale radio-ulnaire gewricht</strong> draait de radius om de ulnakop. Het wordt gestabiliseerd door het triangulair fibrocartilagineus complex (TFCC). Letsel ontstaat bijvoorbeeld bij een distale radiusfractuur of Galeazzi-fractuur, met instabiliteit en pijn bij draaien.</p>","image_url":"","wiki_title":"Distal radioulnar joint","match":"articulatio radio-ulnaris distalis|distaal radio-ulnair gewricht|druj","option_only":true},"articulatio tibiofibularis superior":{"title":"Proximaal tibiofibulair gewricht","short":"Het proximale tibiofibulaire gewricht is een vlak gewricht tussen het caput fibulae en de laterale tibiacondyl.","definition":"<p>Het <strong>proximale tibiofibulaire gewricht</strong> maakt kleine glijbewegingen mogelijk bij beweging in de enkel. Het hoort niet bij het kniegewricht zelf. Een luxatie is zeldzaam en kan de n. fibularis communis bedreigen.</p>","image_url":"","wiki_title":"Superior tibiofibular joint","match":"articulatio tibiofibularis superior|proximaal tibiofibulair gewricht","option_only":true},"n. saphenus":{"title":"N. saphenus","short":"De n. saphenus is de sensibele eindtak van de n. femoralis voor de mediale zijde van onderbeen en voet.","definition":"<p>De <strong>n. saphenus</strong> loopt met de a. femoralis door het kanaal van Hunter en daarna samen met de v. saphena magna langs de mediale zijde van het onderbeen. Hij kan beschadigd raken bij varicesoperaties, knieoperaties of het oogsten van de vene voor een bypass.</p>","image_url":"","wiki_title":"Saphenous nerve","match":"n. saphenus|nervus saphenus","option_only":true},"n. suralis":{"title":"N. suralis","short":"De n. suralis is een sensibele zenuw voor de laterale zijde van voet en enkel.","definition":"<p>De <strong>n. suralis</strong> loopt met de v. saphena parva achter de malleolus lateralis. Omdat het een zuiver sensibele zenuw is, wordt hij gebruikt voor zenuwbiopten (bijv. bij vasculitis) en geleidingsonderzoek bij polyneuropathie.</p>","image_url":"","wiki_title":"Sural nerve","match":"n. suralis|nervus suralis","option_only":true},"n. cutaneus antebrachii lateralis":{"title":"N. cutaneus antebrachii lateralis","short":"De n. cutaneus antebrachii lateralis is de sensibele eindtak van de n. musculocutaneus voor de laterale zijde van de onderarm.","definition":"<p>De <strong>n. cutaneus antebrachii lateralis</strong> komt in de elleboogplooi lateraal van de bicepspees naar oppervlakkig, vlak bij de v. cephalica, en verzorgt de huid aan de radiale zijde van de onderarm. Hij kan geraakt worden bij venapuncties.</p>","image_url":"","wiki_title":"Lateral cutaneous nerve of forearm","match":"n. cutaneus antebrachii lateralis","option_only":true},"n. cutaneus femoris posterior":{"title":"N. cutaneus femoris posterior","short":"De n. cutaneus femoris posterior (S1–S3) verzorgt de huid van bil, perineum en achterzijde van de dij.","definition":"<p>De <strong>n. cutaneus femoris posterior</strong> verlaat het bekken onder de m. piriformis, samen met de n. ischiadicus, en loopt onder de fascie aan de achterzijde van het bovenbeen. Het is een zuiver sensibele zenuw.</p>","image_url":"","wiki_title":"Posterior cutaneous nerve of thigh","match":"n. cutaneus femoris posterior","option_only":true},"dropping hand":{"title":"Dropshand","short":"Bij een dropshand kan iemand pols en vingers niet strekken, meestal door uitval van de n. radialis.","definition":"<p>Een <strong>dropshand</strong> ontstaat door verlamming van de extensoren van pols en vingers. Oorzaken zijn een letsel van de n. radialis bij een humerusschachtfractuur, langdurige druk (‘zaterdagnachtverlamming’) of een C7-radiculopathie. Ook de grijpkracht neemt af, omdat de pols niet in extensie kan worden gestabiliseerd.</p>","image_url":"","wiki_title":"Wrist drop","match":"dropping hand|dropshand|drophand|polsdrop","option_only":true},"femurfractuur":{"title":"Femurfractuur","short":"Een femurfractuur is een breuk van het dijbeen; bij ouderen vooral in het collum (heupfractuur), bij jongeren vaak in de schacht door hoog geweld.","definition":"<p><strong>Heupfracturen</strong> bij ouderen (mediale collumfractuur of pertrochantere fractuur) ontstaan vaak na een val bij osteoporose; het been staat verkort en naar buiten gedraaid. Ze hebben een hoge sterfte en morbiditeit. Schachtfracturen kunnen veel bloedverlies geven. Behandeling is meestal operatief.</p>","image_url":"","wiki_title":"Femoral fracture","match":"femurfractuur|bovenbeenbreuk|heupfractuur","option_only":true},"humerusfractuur":{"title":"Humerusfractuur","short":"Een humerusfractuur is een breuk van het opperarmbeen; proximaal vooral bij ouderen, in de schacht met risico op letsel van de n. radialis.","definition":"<p><strong>Proximale humerusfracturen</strong> komen vooral bij oudere vrouwen met osteoporose voor en worden vaak conservatief behandeld. Bij een fractuur van het collum chirurgicum kan de n. axillaris beschadigd raken, bij een schachtfractuur de n. radialis (dropshand) en bij een suprachondylaire fractuur bij kinderen de a. brachialis en n. medianus.</p>","image_url":"","wiki_title":"Humerus fracture","match":"humerusfractuur|proximale humerusfractuur|bovenarmbreuk","option_only":true},"radiusfractuur":{"title":"Distale radiusfractuur","short":"Een distale radiusfractuur is een breuk van het spaakbeen vlak boven de pols, meestal na een val op de uitgestrekte hand.","definition":"<p>Bij de klassieke <strong>Colles-fractuur</strong> is het distale fragment naar dorsaal gekanteld (‘vorkstand’). Bij ouderen wijst het vaak op osteoporose. Behandeling: repositie en gips of operatieve fixatie. Complicaties zijn standsafwijkingen, ruptuur van de pees van de m. extensor pollicis longus, carpaletunnelsyndroom en complex regionaal pijnsyndroom.</p>","image_url":"","wiki_title":"Distal radius fracture","match":"radiusfractuur|distale radiusfractuur|polsfractuur|colles-fractuur","option_only":true},"claviculafractuur":{"title":"Claviculafractuur","short":"Een claviculafractuur is een breuk van het sleutelbeen, meestal in het middelste derde na een val op de schouder.","definition":"<p><strong>Claviculafracturen</strong> komen veel voor bij kinderen en jongvolwassenen. Het mediale fragment wordt door de m. sternocleidomastoideus omhoog getrokken. De meeste genezen goed met een mitella; bij grote verplaatsing of verkorting kan operatie nodig zijn. Zelden raken de onderliggende vaten of plexus brachialis beschadigd.</p>","image_url":"","wiki_title":"Clavicle fracture","match":"claviculafractuur|sleutelbeenbreuk","option_only":true},"elleboogluxatie":{"title":"Elleboogluxatie","short":"Bij een elleboogluxatie schieten ulna en radius uit het gewricht met de humerus, meestal naar achteren.","definition":"<p>Een <strong>posterieure elleboogluxatie</strong> ontstaat bij een val op de uitgestrekte arm. Controleer altijd de doorbloeding (a. brachialis) en de zenuwen (n. ulnaris, n. medianus). Bij jonge kinderen komt vooral de ‘zondagsarmpje’-subluxatie van de radiuskop voor, door trekken aan de gestrekte arm.</p>","image_url":"","wiki_title":"Elbow dislocation","match":"elleboogluxatie","option_only":true},"ligamentum talofibulare posterius":{"title":"Ligamentum talofibulare posterius","short":"Het ligamentum talofibulare posterius is de sterkste laterale enkelband, van de malleolus lateralis naar de achterzijde van de talus.","definition":"<p>Het <strong>lig. talofibulare posterius</strong> loopt vrijwel horizontaal en raakt bij een gewoon inversietrauma zelden beschadigd; dat gebeurt pas bij ernstige letsels zoals een enkelluxatie.</p>","image_url":"","wiki_title":"Posterior talofibular ligament","match":"ligamentum talofibulare posterius","option_only":true},"meniscus":{"title":"Meniscus","short":"De menisci zijn halvemaanvormige schijven van vezelig kraakbeen in de knie die druk verdelen en schokken opvangen.","definition":"<p>De <strong>mediale meniscus</strong> is C-vormig en vast verbonden met het mediale collaterale ligament, waardoor hij vaker scheurt dan de meer O-vormige laterale meniscus. Een scheur ontstaat bij jongeren door een draaitrauma, bij ouderen degeneratief. Klachten: pijn op de gewrichtsspleet, zwelling en soms slotklachten.</p>","image_url":"","wiki_title":"Meniscus (anatomy)","match":"meniscus|menisci|meniscusletsel","option_only":true},"diep veneuze trombose":{"title":"Trombosebeen (diepveneuze trombose)","short":"Een trombosebeen is een stolsel in een diepe vene van het been, met een dik, pijnlijk, warm been.","definition":"<p>Bij een <strong>diepveneuze trombose</strong> ontstaat een stolsel in de diepe venen, meestal in de kuit of bovenbeen. Risicofactoren volgen de trias van Virchow: stase, hypercoagulabiliteit en vaatwandschade (bijv. operatie, immobilisatie, kanker, zwangerschap, oestrogenen). Diagnostiek met een beslisregel (Wells), D-dimeer en compressie-echografie. De belangrijkste complicatie is een longembolie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Deep vein thrombosis","match":"diep veneuze trombose","option_only":true},"reumatoide artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoide artritis","option_only":true},"ligamentum deltoideum":{"title":"Ligamentum deltoideum","short":"Het ligamentum deltoideum is de sterke, waaiervormige band aan de binnenzijde van de enkel.","definition":"<p>Het <strong>lig. deltoideum</strong> loopt van de malleolus medialis naar os naviculare, talus en calcaneus en heeft een oppervlakkige en een diepe laag. Het is veel sterker dan de laterale enkelbanden en stabiliseert de enkel aan de mediale zijde.</p>","image_url":"","wiki_title":"Deltoid ligament","match":"ligamentum deltoideum","option_only":true},"ligamentum calcaneofibulare":{"title":"Ligamentum calcaneofibulare","short":"Het ligamentum calcaneofibulare is een laterale enkelband van de malleolus lateralis naar de calcaneus.","definition":"<p>Het <strong>lig. calcaneofibulare</strong> vormt met het lig. talofibulare anterius en posterius het laterale bandcomplex van de enkel en overspant zowel het bovenste als het onderste spronggewricht.</p>","image_url":"","wiki_title":"Calcaneofibular ligament","match":"ligamentum calcaneofibulare","option_only":true},"beenvarices":{"title":"Varices (spataderen)","short":"Varices zijn verwijde, kronkelige oppervlakkige venen in de benen, door lekkende kleppen.","definition":"<p><strong>Spataderen</strong> komen veel voor, vaker bij vrouwen, met familiaire aanleg, zwangerschap, overgewicht en staand werk als risicofactoren. Klachten: zware, moeë benen, jeuk en oedeem; complicaties zijn tromboflebitis, bloedingen, huidveranderingen en een ulcus cruris. Behandeling: compressie, sclerotherapie, endoveneuze ablatie.</p>","image_url":"","wiki_title":"Varicose veins","match":"beenvarices|varices|spataderen","option_only":true},"reumafactor":{"title":"Reumafactor","short":"Reumafactor is een auto-antistof (meestal IgM) tegen het Fc-deel van IgG; hij komt voor bij reumatoïde artritis maar ook bij andere ziekten.","definition":"<p><strong>Reumafactor</strong> is positief bij ongeveer 70–80% van de patiënten met reumatoïde artritis, maar ook bij het syndroom van Sjögren, chronische infecties (hepatitis C, endocarditis) en bij gezonde ouderen. Anti-CCP is specifieker voor RA.</p>","image_url":"","wiki_title":"Rheumatoid factor","match":"reumafactor|rf","option_only":true},"jicht (artritis urica)":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jicht (artritis urica)","option_only":true},"voorste schouderluxatie":{"title":"Schouderluxatie","short":"Bij een schouderluxatie schiet de humeruskop uit de kom, meestal naar voren-onder.","definition":"<p>Bij een <strong>anterieure schouderluxatie</strong> (verreweg het meest voorkomend) staat de arm in lichte abductie en exorotatie, met een afgeplatte schouderronding en een leeg gevoel onder het acromion. Controleer altijd de n. axillaris (gevoel op de schouder). Bij jongeren is recidief luxeren vaak; bij ouderen komen cuffscheuren voor. Posterieure luxaties komen voor bij epileptische aanvallen en elektrocutie.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"voorste schouderluxatie","option_only":true},"parathyreoïd hormoon":{"title":"Parathyreoïd hormoon (PTH)","short":"PTH is het hormoon van de bijschildklieren dat de calciumspiegel in het bloed verhoogt.","definition":"<p><strong>PTH</strong> wordt afgegeven bij een daling van het geïoniseerde calcium. Het stimuleert (via osteoblasten en RANKL) botafbraak, verhoogt de calciumterugresorptie en fosfaatuitscheiding in de nier en activeert vitamine D. Overmaat geeft hyperparathyreoïdie met hypercalciëmie.</p>","image_url":"","wiki_title":"Parathyroid hormone","match":"parathyreoïd hormoon|pth|parathormoon|bijschildklierhormoon","option_only":true},"endorotatie":{"title":"Endorotatie","short":"Endorotatie is draaien van een ledemaat om de lengteas naar binnen (mediaal).","definition":"<p>Bij <strong>endorotatie</strong> draait de voorzijde van bijv. bovenarm of bovenbeen naar binnen. In de schouder zijn de m. subscapularis, m. pectoralis major en m. latissimus dorsi belangrijke endorotatoren. Bij coxartrose is de endorotatie van de heup vaak als eerste beperkt.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"endorotatie|interne rotatie|binnenwaartse rotatie","option_only":true},"adductie":{"title":"Adductie","short":"Adductie is een beweging van een lichaamsdeel naar de middellijn toe; het tegenovergestelde van abductie.","definition":"<p>Bij <strong>adductie</strong> beweegt een ledemaat in het frontale vlak naar het lichaam toe. De adductoren van de heup (m. adductor longus, brevis, magnus, m. gracilis) worden geïnnerveerd door de n. obturatorius.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"adductie","option_only":true},"circumductie":{"title":"Circumductie","short":"Circumductie is een kegelvormige rondgaande beweging van een ledemaat, een combinatie van flexie, abductie, extensie en adductie.","definition":"<p><strong>Circumductie</strong> is mogelijk in kogelgewrichten (schouder, heup) en in tweeassige gewrichten zoals de pols. Bij een ‘maaiend’ looppatroon na een beroerte zwaait het been in een boog naar buiten.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"circumductie","option_only":true},"palmairflexie":{"title":"Palmairflexie","short":"Palmairflexie is het buigen van de hand richting de handpalm in het polsgewricht.","definition":"<p>Bij <strong>palmairflexie</strong> buigt de pols naar de handpalmzijde; de tegenbeweging is dorsaalflexie (extensie). De belangrijkste polsflexoren zijn de m. flexor carpi radialis en ulnaris. De test van Phalen (maximale palmairflexie) lokt klachten uit bij het carpaletunnelsyndroom.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"palmairflexie|volairflexie","option_only":true},"anteflexie":{"title":"Anteflexie","short":"Anteflexie is het naar voren heffen of buigen van een lichaamsdeel, bijvoorbeeld de arm in het schoudergewricht.","definition":"<p>In de schouder heet flexie ook <strong>anteflexie</strong>; de tegenbeweging is retroflexie (extensie). Voor de uterus betekent anteflexie de normale knik tussen corpus en cervix naar voren.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"anteflexie","option_only":true},"retroflexie":{"title":"Retroflexie","short":"Retroflexie is het naar achteren bewegen of buigen van een lichaamsdeel, zoals de arm in de schouder.","definition":"<p>Bij de schouder is <strong>retroflexie</strong> de beweging van de arm naar achteren (extensie). Bij de uterus betekent retroflexie een naar achteren geknikt corpus, een normvariant.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"retroflexie","option_only":true},"n. tibialis":{"title":"N. tibialis","short":"De n. tibialis is een eindtak van de n. ischiadicus die de kuitspieren en de voetzool innerveert.","definition":"<p>De <strong>n. tibialis</strong> loopt door de knieholte en achter de malleolus medialis door de tarsale tunnel naar de voetzool. Hij innerveert de plantairflexoren en de kleine voetspieren en sensibel de voetzool. Beknelling achter de malleolus heet het tarsaletunnelsyndroom.</p>","image_url":"","wiki_title":"Tibial nerve","match":"n. tibialis|nervus tibialis","option_only":true},"n. fibularis communis":{"title":"N. fibularis (peroneus) communis","short":"De n. fibularis communis loopt om het collum fibulae en splitst in een diepe en oppervlakkige tak; uitval geeft een klapvoet.","definition":"<p>De <strong>n. fibularis communis</strong> ligt oppervlakkig rond de fibulakop en raakt daar makkelijk bekneld (benen over elkaar slaan, gips, gewichtsverlies, fractuur). Uitval geeft een voetheffersparese met klapvoet en gevoelsstoornis aan de voetrug. Het onderscheid met een L5-radiculopathie: bij een peroneusletsel is de inversie (m. tibialis posterior) intact.</p>","image_url":"","wiki_title":"Common fibular nerve","match":"n. fibularis communis|n. peroneus communis|nervus peroneus","option_only":true},"a. carotis communis":{"title":"A. carotis communis","short":"De a. carotis communis loopt in de hals omhoog en splitst ter hoogte van het schildkraakbeen in de a. carotis interna en externa.","definition":"<p>Rechts komt de <strong>a. carotis communis</strong> uit de truncus brachiocephalicus, links rechtstreeks uit de aortaboog. Bij de splitsing liggen de sinus caroticus (baroreceptoren) en het glomus caroticum (chemoreceptoren). De carotispols is lateraal van het strottenhoofd voelbaar.</p>","image_url":"","wiki_title":"Common carotid artery","match":"a. carotis communis|arteria carotis communis|a.carotis|halsslagader","option_only":true},"clavicula":{"title":"Clavicula (sleutelbeen)","short":"De clavicula is het S-vormige bot dat het borstbeen met het schouderblad verbindt.","definition":"<p>De <strong>clavicula</strong> houdt de schouder op afstand van de romp en draagt krachten van de arm over naar het axiale skelet. Ze is het eerste bot dat verbeent (desmaal). Onder de clavicula lopen de vasa subclavia en de plexus brachialis.</p>","image_url":"","wiki_title":"Clavicle","match":"clavicula|sleutelbeen","option_only":true},"ligamentum cruciatum posterius":{"title":"Achterste kruisband","short":"De achterste kruisband voorkomt dat de tibia ten opzichte van de femur naar achteren schuift.","definition":"<p>Een letsel van de <strong>achterste kruisband</strong> ontstaat door een klap op het onderbeen bij gebogen knie (dashboardletsel) of een val op de gebogen knie. Er is een positieve achterste schuiflade en een ‘sag sign’. Het wordt vaak conservatief behandeld.</p>","image_url":"","wiki_title":"Posterior cruciate ligament","match":"ligamentum cruciatum posterius|achterste kruisband|pcl","option_only":true},"ligamentum collaterale laterale":{"title":"Lateraal collateraal ligament (knie)","short":"Het laterale collaterale ligament van de knie loopt van de femur naar de fibulakop en stabiliseert de knie tegen varusbelasting.","definition":"<p>Het <strong>LCL</strong> ligt buiten het gewrichtskapsel en is niet verbonden met de meniscus (anders dan het mediale collaterale ligament). Letsel ontstaat bij een klap aan de binnenkant van de knie en gaat soms samen met letsel van de n. fibularis.</p>","image_url":"","wiki_title":"Fibular collateral ligament","match":"ligamentum collaterale laterale|lateraal collateraal ligament|lcl","option_only":true},"greenstick fractuur":{"title":"Greenstickfractuur","short":"Een greenstickfractuur is een onvolledige fractuur bij kinderen, waarbij het bot aan één kant breekt en aan de andere kant buigt.","definition":"<p>Het bot van kinderen is soepeler en het periost dikker, waardoor naast <strong>greenstickfracturen</strong> ook torusfracturen (opbollen van de cortex) en buigfracturen voorkomen. Fracturen door de groeischijf (Salter-Harris) kunnen groeistoornissen geven.</p>","image_url":"","wiki_title":"Greenstick fracture","match":"greenstick fractuur|greenstickfractuur","option_only":true},"avulsiefractuur":{"title":"Avulsiefractuur","short":"Bij een avulsiefractuur trekt een pees of band een stukje bot los van zijn aanhechting.","definition":"<p><strong>Avulsiefracturen</strong> komen vooral voor bij jongeren (sterkere pezen dan apofysen), bijv. aan de spina iliaca of tuberositas ischiadica bij sporters, en bij de basis van metatarsale V na een inversietrauma.</p>","image_url":"","wiki_title":"Avulsion fracture","match":"avulsiefractuur|avulsie","option_only":true},"lig. talofibulaire posterius":{"title":"Ligamentum talofibulare posterius","short":"Het ligamentum talofibulare posterius is de sterkste laterale enkelband, van de malleolus lateralis naar de achterzijde van de talus.","definition":"<p>Het <strong>lig. talofibulare posterius</strong> loopt vrijwel horizontaal en raakt bij een gewoon inversietrauma zelden beschadigd; dat gebeurt pas bij ernstige letsels zoals een enkelluxatie.</p>","image_url":"","wiki_title":"Posterior talofibular ligament","match":"lig. talofibulaire posterius","option_only":true},"claudicatio intermittens":{"title":"Claudicatio intermittens","short":"Claudicatio intermittens is pijn in de kuit of bil bij lopen die bij stilstaan verdwijnt, door perifeer arterieel vaatlijden.","definition":"<p>Bij <strong>claudicatio</strong> zijn de beenarteriën vernauwd door atherosclerose. De enkel-armindex is verlaagd (&lt;0,9). Behandeling: stoppen met roken, gesuperviseerde looptraining, een plaatjesremmer en statine; bij ernstige klachten of kritieke ischemie (rustpijn, wonden) revascularisatie.</p>","image_url":"","wiki_title":"Intermittent claudication","match":"claudicatio intermittens|etalagebenen|perifeer arterieel vaatlijden","option_only":true},"de ziekte van paget":{"title":"Ziekte van Paget (osteitis deformans)","short":"De ziekte van Paget van het bot is een stoornis met sterk verhoogde, ongeordende botombouw, waardoor botten groter en zwakker worden.","definition":"<p>Bij de <strong>ziekte van Paget</strong> zijn vaak bekken, schedel, wervels en lange pijpbeenderen aangedaan. Het alkalisch fosfatase is sterk verhoogd bij een normaal calcium. Klachten: botpijn, vervorming, fracturen, doofheid (schedel) en zelden een osteosarcoom. Behandeling met bisfosfonaten.</p>","image_url":"","wiki_title":"Paget's disease of bone","match":"de ziekte van paget|ziekte van paget|osteitis deformans","option_only":true},"osteopetrose":{"title":"Osteopetrose","short":"Bij osteopetrose werken osteoclasten niet goed, waardoor bot te dicht maar broos wordt en het beenmerg wordt verdrongen.","definition":"<p>Bij <strong>osteopetrose</strong> ontstaan fracturen, beenmergfalen (anemie, infecties, extramedullaire bloedaanmaak) en uitval van hersenzenuwen door vernauwde schedelopeningen. De ernstige infantiele vorm wordt met stamceltransplantatie behandeld.</p>","image_url":"","wiki_title":"Osteopetrosis","match":"osteopetrose|marmerbeenziekte","option_only":true},"rachitis (= rickets)":{"title":"Rachitis (Engelse ziekte)","short":"Rachitis is een stoornis in de mineralisatie van groeiend bot bij kinderen, meestal door vitamine D-tekort.","definition":"<p>Kenmerken van <strong>rachitis</strong> zijn O-benen, verbrede polsen, een ‘rozenkrans’ aan de ribben, een uitgesteld sluiten van de fontanel en groeiachterstand. Het alkalisch fosfatase is verhoogd. Risico bij een donkere huid, weinig zonlicht en volledige borstvoeding zonder vitamine D-suppletie. Bij volwassenen heet het osteomalacie.</p>","image_url":"","wiki_title":"Rickets","match":"rachitis (= rickets)|rachitis|rickets|engelse ziekte","option_only":true},"antinucleaire factor (anf)":{"title":"Antinucleaire antistoffen (ANA)","short":"Antinucleaire antistoffen zijn auto-antistoffen tegen kerncomponenten; een positieve ANA past bij SLE en andere bindweefselziekten, maar is weinig specifiek.","definition":"<p>De <strong>ANA</strong> wordt bepaald met immunofluorescentie. Ze is bijna altijd positief bij SLE (gevoelig), maar ook bij Sjögren, systemische sclerose, geneesmiddel-lupus en bij een deel van de gezonde mensen (vooral ouderen). Daarom wordt bij een positieve ANA verder gekeken naar specifieke antistoffen (dsDNA, Sm, SSA, SSB, Scl-70).</p>","image_url":"","wiki_title":"Antinuclear antibody","match":"antinucleaire factor (anf)|ana|antinucleaire antistoffen","option_only":true},"rankl":{"title":"RANKL","short":"RANKL is een signaalstof van osteoblasten die osteoclasten activeert; denosumab is een antistof die RANKL remt.","definition":"<p>Het evenwicht tussen <strong>RANKL</strong> en zijn natuurlijke remmer osteoprotegerine bepaalt de botafbraak. Oestrogeentekort, PTH en ontsteking verhogen RANKL. Denosumab remt RANKL en wordt gebruikt bij osteoporose en botmetastasen; na stoppen kan de botafbraak snel terugkeren.</p>","image_url":"","wiki_title":"RANKL","match":"rankl|rank-ligand|denosumab","option_only":true},"calciumpyrofosfaat":{"title":"Calciumpyrofosfaatkristallen (pseudojicht)","short":"Calciumpyrofosfaatkristallen veroorzaken pseudojicht: een acute artritis, vaak van de knie of pols, bij ouderen.","definition":"<p>Bij <strong>CPPD</strong> zijn er rhomboïde, zwak positief dubbelbrekende kristallen in het gewrichtsvocht en kalkafzetting in het kraakbeen op de röntgenfoto (chondrocalcinose). Het is geassocieerd met hemochromatose, hyperparathyreoïdie en hypomagnesiëmie.</p>","image_url":"","wiki_title":"Calcium pyrophosphate dihydrate crystal deposition disease","match":"calciumpyrofosfaat|pseudojicht|chondrocalcinose|cppd","option_only":true},"plexiform bot":{"title":"Plexiform (primair) bot","short":"Plexiform of primair bot is onrijp bot met ongeordende collageenvezels, dat ontstaat bij snelle botvorming en later wordt vervangen door lamellair bot.","definition":"<p><strong>Primair bot</strong> komt voor bij de embryonale botvorming, in fractuurcallus en bij ziekten met verhoogde botaanmaak (ziekte van Paget, tumoren). Het is mechanisch zwakker dan het geordende lamellaire (secundaire) bot.</p>","image_url":"","wiki_title":"Woven bone","match":"plexiform bot|primair botweefsel|woven bone|vezelbot","option_only":true},"enchondrale botvorming":{"title":"Enchondrale ossificatie","short":"Bij enchondrale ossificatie wordt eerst een kraakbeenmodel gevormd dat daarna geleidelijk door bot wordt vervangen; zo ontstaan de meeste botten.","definition":"<p>Bij <strong>enchondrale ossificatie</strong> ontstaan primaire en secundaire verbeningskernen; de groeischijf tussen epifyse en metafyse zorgt voor lengtegroei. Bij desmale ossificatie (schedeldak, clavicula) ontstaat bot direct uit mesenchym. Achondroplasie is een stoornis in de enchondrale verbening.</p>","image_url":"","wiki_title":"Endochondral ossification","match":"enchondrale botvorming|enchondrale ossificatie","option_only":true},"bruin vetweefsel":{"title":"Bruin vetweefsel","short":"Bruin vetweefsel bevat veel kleine vetdruppels en mitochondriën met UCP1 en dient om warmte te maken.","definition":"<p><strong>Bruin vet</strong> ontkoppelt de ademhalingsketen via thermogenine (UCP1), zodat energie als warmte vrijkomt. Pasgeborenen hebben er veel van (tussen de schouderbladen, rond de nieren), omdat ze nog niet kunnen rillen. Het wordt geactiveerd door kou via noradrenaline (β3-receptoren).</p>","image_url":"","wiki_title":"Brown adipose tissue","match":"bruin vetweefsel|plurivacuolair vetweefsel|multiloculair vetweefsel","option_only":true},"osteocyt":{"title":"Osteocyt","short":"Een osteocyt is een botcel die is ingesloten in de botmatrix en via uitlopers met andere botcellen communiceert.","definition":"<p><strong>Osteocyten</strong> ontstaan uit osteoblasten die zich hebben ingemetseld. Ze liggen in lacunes en zijn verbonden via canaliculi. Ze meten mechanische belasting en sturen zo de botombouw (o.a. via sclerostine en RANKL), en maken FGF23, dat de fosfaathuishouding regelt.</p>","image_url":"","wiki_title":"Osteocyte","match":"osteocyt|osteocyten","option_only":true},"osteoïd":{"title":"Osteoïd","short":"Osteoïd is de nog niet gemineraliseerde botmatrix, vooral collageen type I, die door osteoblasten wordt afgezet.","definition":"<p>Na afzetting wordt <strong>osteoïd</strong> binnen enkele dagen gemineraliseerd met hydroxyapatiet. Bij osteomalacie en rachitis (vitamine D-tekort) blijft er te veel ongemineraliseerd osteoïd over, waardoor bot zacht wordt.</p>","image_url":"","wiki_title":"Osteoid","match":"osteoïd|osteoid","option_only":true},"endost":{"title":"Endost","short":"Het endost is het dunne laagje cellen dat de binnenkant van het bot bekleedt, langs de mergholte en de trabekels.","definition":"<p>Het <strong>endost</strong> bevat osteoprogenitorcellen, osteoblasten en osteoclasten en speelt een rol bij botombouw en fractuurgenezing. Het periost bekleedt de buitenkant van het bot.</p>","image_url":"","wiki_title":"Endosteum","match":"endost","option_only":true},"fibrilline":{"title":"Fibrilline","short":"Fibrilline is een glycoproteïne dat microfibrillen vormt, het geraamte voor elastische vezels.","definition":"<p>Mutaties in het <strong>fibrilline-1</strong>-gen (FBN1) veroorzaken het syndroom van Marfan. Fibrilline bindt ook TGF-β; bij een defect is de TGF-β-signalering verhoogd, wat bijdraagt aan aortaverwijding.</p>","image_url":"","wiki_title":"Fibrillin","match":"fibrilline|fibrilline-1","option_only":true},"ligamentum flavum":{"title":"Ligamentum flavum","short":"De ligamenta flava zijn elastische banden tussen de wervelbogen, aan de achterkant van het wervelkanaal.","definition":"<p>Het <strong>ligamentum flavum</strong> geeft door zijn elasticiteit een voorspanning en helpt de wervelkolom terugveren uit flexie. Bij een epidurale of lumbaalpunctie voelt men een ‘pop’ bij het doorprikken. Verdikking ervan draagt bij aan lumbale kanaalstenose.</p>","image_url":"","wiki_title":"Ligamenta flava","match":"ligamentum flavum|ligamenta flava","option_only":true},"ligamentum nuchae":{"title":"Ligamentum nuchae","short":"Het ligamentum nuchae is een stevige band in de nek tussen het achterhoofd en de doornuitsteeksels van de halswervels.","definition":"<p>Het <strong>ligamentum nuchae</strong> is de voortzetting van het lig. supraspinale in de nek en dient als aanhechting voor nekspieren. Tussen de doornuitsteeksels liggen de ligamenta interspinalia.</p>","image_url":"","wiki_title":"Nuchal ligament","match":"ligamentum nuchae|ligamentum supraspinale|ligamentum interspinale","option_only":true},"lig. longitudinale posterius":{"title":"Ligamentum longitudinale posterius","short":"Het ligamentum longitudinale posterius loopt over de achterkant van de wervellichamen in het wervelkanaal.","definition":"<p>Het <strong>lig. longitudinale posterius</strong> is in de lumbale regio smal, waardoor een hernia vaak naar posterolateraal uitpuilt en een zenuwwortel prikkelt. Het lig. longitudinale anterius aan de voorzijde is breder en sterker.</p>","image_url":"","wiki_title":"Posterior longitudinal ligament","match":"lig. longitudinale posterius|ligamentum longitudinale posterius","option_only":true},"lig. longitudinale anterius":{"title":"Ligamentum longitudinale anterius","short":"Het ligamentum longitudinale anterius is een brede, sterke band over de voorkant van de wervellichamen en tussenwervelschijven.","definition":"<p>Het <strong>lig. longitudinale anterius</strong> beperkt de extensie van de wervelkolom. Bij de ziekte van Bechterew en DISH kan het verbenen.</p>","image_url":"","wiki_title":"Anterior longitudinal ligament","match":"lig. longitudinale anterius|ligamentum longitudinale anterius","option_only":true},"anulus fibrosus":{"title":"Anulus fibrosus","short":"De anulus fibrosus is de buitenring van de tussenwervelschijf, opgebouwd uit lagen vezelig kraakbeen.","definition":"<p>De <strong>anulus fibrosus</strong> omsluit de nucleus pulposus. Scheurtjes in de anulus, vooral posterolateraal, maken een hernia nuclei pulposi mogelijk.</p>","image_url":"","wiki_title":"Annulus fibrosus disci intervertebralis","match":"anulus fibrosus|annulus fibrosus","option_only":true},"articulatio genus":{"title":"Kniegewricht (articulatio genus)","short":"Het kniegewricht is het gewricht tussen femur, tibia en patella, gestabiliseerd door kruisbanden, collaterale banden en menisci.","definition":"<p>De <strong>knie</strong> is vooral een scharniergewricht met in gebogen stand enige rotatie. De voorste kruisband voorkomt naar voren schuiven van de tibia, de achterste naar achteren; de collaterale banden geven zijdelingse stabiliteit. Letsels ontstaan vaak bij draaibewegingen in sport.</p>","image_url":"","wiki_title":"Knee","match":"articulatio genus|kniegewricht|knie","option_only":true},"articulatio cubiti":{"title":"Ellebooggewricht (articulatio cubiti)","short":"Het ellebooggewricht bestaat uit drie gewrichten: humero-ulnair, humeroradiaal en proximaal radio-ulnair.","definition":"<p>Het <strong>ellebooggewricht</strong> maakt flexie en extensie (humero-ulnair, scharnier) en pro- en supinatie (radio-ulnair, draaigewricht) mogelijk. Aan de mediale epicondyl hechten de flexoren aan (golferselleboog), aan de laterale de extensoren (tenniselleboog).</p>","image_url":"","wiki_title":"Elbow","match":"articulatio cubiti|ellebooggewricht|elleboog","option_only":true},"articulatio acromioclavicularis":{"title":"Acromioclaviculair gewricht","short":"Het AC-gewricht verbindt het acromion met het laterale uiteinde van de clavicula.","definition":"<p>Een <strong>AC-luxatie</strong> ontstaat bij een val op de schouder; bij ernstige vormen zijn ook de coracoclaviculaire banden gescheurd en staat de clavicula hoog (pianotoetsfenomeen). Artrose van het AC-gewricht geeft pijn bovenop de schouder, vooral bij armheffen boven het hoofd.</p>","image_url":"","wiki_title":"Acromioclavicular joint","match":"articulatio acromioclavicularis|ac-gewricht|acromioclaviculair gewricht|ac-luxatie","option_only":true},"acromion":{"title":"Acromion","short":"Het acromion is het platte uitsteeksel van de spina scapulae dat het hoogste punt van de schouder vormt.","definition":"<p>Het <strong>acromion</strong> vormt met het lig. coracoacromiale het dak van de subacromiale ruimte, waar de supraspinatuspees en bursa onder doorlopen. Een haakvormig acromion kan bijdragen aan subacromiale klachten.</p>","image_url":"","wiki_title":"Acromion","match":"acromion","option_only":true},"ligamentum collaterale mediale":{"title":"Mediaal collateraal ligament (knie)","short":"Het mediale collaterale ligament van de knie loopt van de mediale femurcondyl naar de tibia en beschermt tegen valgusbelasting.","definition":"<p>Het <strong>MCL</strong> is verbonden met het kapsel en de mediale meniscus. Letsels ontstaan bij een klap tegen de buitenkant van de knie en genezen meestal goed conservatief. Bij de ‘unhappy triad’ zijn MCL, voorste kruisband en mediale meniscus samen beschadigd.</p>","image_url":"","wiki_title":"Medial collateral ligament","match":"ligamentum collaterale mediale|mcl|mediale collaterale band","option_only":true},"ligamentum patellae":{"title":"Ligamentum patellae (patellapees)","short":"Het ligamentum patellae verbindt de knieschijf met de tuberositas tibiae en is de voortzetting van de quadricepspees.","definition":"<p>Overbelasting van de <strong>patellapees</strong> geeft een jumper's knee; bij groeiende kinderen een Osgood-Schlatter (tuberositas) of Sinding-Larsen-Johansson (onderpool patella). De kniepeesreflex wordt opgewekt door op de patellapees te tikken (L3–L4).</p>","image_url":"","wiki_title":"Patellar ligament","match":"ligamentum patellae|patellapees","option_only":true},"laterale meniscus":{"title":"Laterale meniscus","short":"De laterale meniscus is de bijna cirkelvormige, beweeglijke meniscus aan de buitenkant van de knie.","definition":"<p>Omdat de <strong>laterale meniscus</strong> niet vastzit aan het laterale collaterale ligament, is hij beweeglijker en scheurt hij minder vaak dan de mediale. Een discoïde laterale meniscus is een aangeboren variant die bij kinderen klachten kan geven.</p>","image_url":"","wiki_title":"Lateral meniscus","match":"laterale meniscus","option_only":true},"tarsaal tunnel syndroom":{"title":"Tarsaletunnelsyndroom","short":"Bij het tarsaletunnelsyndroom is de n. tibialis bekneld achter de malleolus medialis, met branderige pijn en tintelingen in de voetzool.","definition":"<p>De <strong>tarsale tunnel</strong> ligt onder het retinaculum flexorum aan de binnenkant van de enkel. Oorzaken van beknelling zijn o.a. een ganglion, varices, littekenweefsel en een platvoet. Het is de tegenhanger van het carpaletunnelsyndroom.</p>","image_url":"","wiki_title":"Tarsal tunnel syndrome","match":"tarsaal tunnel syndroom|tarsaletunnelsyndroom|tarsale tunnel","option_only":true},"meralgia paresthetica":{"title":"Meralgia paraesthetica","short":"Meralgia paraesthetica is beknelling van de n. cutaneus femoris lateralis onder het liesband, met tintelingen en een doof gevoel aan de buitenkant van de dij.","definition":"<p>Uitlokkers van <strong>meralgia paraesthetica</strong> zijn overgewicht, zwangerschap, strakke kleding of riemen. Er is geen krachtsverlies, omdat de zenuw zuiver sensibel is. Meestal gaat het vanzelf over.</p>","image_url":"","wiki_title":"Meralgia paresthetica","match":"meralgia paresthetica|meralgia paraesthetica","option_only":true},"positieve test van lasègue":{"title":"Proef van Lasègue","short":"Bij de proef van Lasègue wordt het gestrekte been geheven; uitstralende pijn in het been tussen 30 en 70° wijst op prikkeling van een lumbosacrale zenuwwortel.","definition":"<p>Een positieve <strong>Lasègue</strong> past bij een lumbosacraal radiculair syndroom (meestal L5 of S1, door een hernia). De gekruiste Lasègue (pijn in het aangedane been bij heffen van het andere) is specifieker.</p>","image_url":"","wiki_title":"Straight leg raise","match":"positieve test van lasègue|proef van lasègue|lasègue|straight leg raise","option_only":true},"n. fibularis superficialis":{"title":"N. fibularis superficialis","short":"De n. fibularis superficialis innerveert de mm. fibulares (eversie) en het grootste deel van de voetrug.","definition":"<p>De <strong>n. fibularis superficialis</strong> is een tak van de n. fibularis communis en loopt in de laterale loge van het onderbeen. Letsel geeft zwakte bij eversie en gevoelsstoornis op de voetrug (behalve de eerste webspace, die bij de n. fibularis profundus hoort).</p>","image_url":"","wiki_title":"Superficial fibular nerve","match":"n. fibularis superficialis|n. peroneus superficialis","option_only":true},"n. dorsalis scapulae":{"title":"N. dorsalis scapulae","short":"De n. dorsalis scapulae (C5) innerveert de mm. rhomboidei en de m. levator scapulae.","definition":"<p>De <strong>n. dorsalis scapulae</strong> komt direct uit de ventrale ramus van C5 en doorboort de m. scalenus medius. Uitval geeft een licht afstaande mediale rand van de scapula.</p>","image_url":"","wiki_title":"Dorsal scapular nerve","match":"n. dorsalis scapulae","option_only":true},"n. subscapularis":{"title":"N. subscapularis","short":"De nn. subscapulares innerveren de m. subscapularis en m. teres major (endorotatoren van de schouder).","definition":"<p>De <strong>nn. subscapulares</strong> (C5–C6) komen uit de fasciculus posterior van de plexus brachialis.</p>","image_url":"","wiki_title":"Subscapular nerve","match":"n. subscapularis|nervi subscapulares","option_only":true},"n. gluteus superior":{"title":"N. gluteus superior","short":"De n. gluteus superior innerveert de m. gluteus medius en minimus, die het bekken stabiliseren bij lopen.","definition":"<p>Bij uitval van de <strong>n. gluteus superior</strong> zakt het bekken bij staan op het aangedane been naar de gezonde kant (teken van Trendelenburg). Letsel kan ontstaan bij een verkeerd geplaatste bilinjectie of heupoperatie.</p>","image_url":"","wiki_title":"Superior gluteal nerve","match":"n. gluteus superior|nervus gluteus superior","option_only":true},"n. gluteus inferior":{"title":"N. gluteus inferior","short":"De n. gluteus inferior innerveert de m. gluteus maximus, de belangrijkste heupextensor.","definition":"<p>Uitval van de <strong>n. gluteus inferior</strong> geeft moeite met traplopen, opstaan uit een stoel en springen. De zenuw verlaat het bekken onder de m. piriformis.</p>","image_url":"","wiki_title":"Inferior gluteal nerve","match":"n. gluteus inferior|nervus gluteus inferior","option_only":true},"a. basilaris":{"title":"A. basilaris","short":"De a. basilaris ontstaat uit de samenvloeiing van de beide aa. vertebrales en voorziet hersenstam, cerebellum en via de aa. cerebri posteriores de occipitaalkwab.","definition":"<p>Een <strong>basilaristrombose</strong> geeft ernstige uitval met o.a. bewustzijnsdaling, tetraparese, oogbewegingsstoornissen en soms een locked-in-syndroom; snelle behandeling is nodig. Bij een top-of-the-basilar-syndroom zijn thalamus en occipitaalkwab aangedaan.</p>","image_url":"","wiki_title":"Basilar artery","match":"a. basilaris|arteria basilaris","option_only":true},"a. brachialis":{"title":"A. brachialis","short":"De a. brachialis is de slagader van de bovenarm, de voortzetting van de a. axillaris, die in de elleboogplooi splitst in de a. radialis en a. ulnaris.","definition":"<p>De <strong>a. brachialis</strong> loopt met de n. medianus aan de mediale zijde van de bovenarm en wordt gebruikt bij het meten van de bloeddruk. Bij een suprachondylaire humerusfractuur bij kinderen kan ze worden beschadigd (risico op compartimentsyndroom).</p>","image_url":"","wiki_title":"Brachial artery","match":"a. brachialis|arteria brachialis","option_only":true},"a. tibialis posterior":{"title":"A. tibialis posterior","short":"De a. tibialis posterior loopt in de achterste loge van het onderbeen naar de voetzool; de pols is voelbaar achter de malleolus medialis.","definition":"<p>Samen met de a. dorsalis pedis wordt de <strong>a. tibialis posterior</strong> gepalpeerd bij het onderzoek naar perifeer arterieel vaatlijden. Ze loopt met de n. tibialis door de tarsale tunnel.</p>","image_url":"","wiki_title":"Posterior tibial artery","match":"a. tibialis posterior|arteria tibialis posterior","option_only":true},"a. femoralis profunda":{"title":"A. profunda femoris","short":"De a. profunda femoris is de diepe tak van de a. femoralis die de spieren van het bovenbeen en via de aa. circumflexae de femurkop voorziet.","definition":"<p>De <strong>a. profunda femoris</strong> geeft perforerende takken af naar de achterzijde van het bovenbeen. Ze is een belangrijke collaterale route bij afsluiting van de a. femoralis superficialis.</p>","image_url":"","wiki_title":"Deep femoral artery","match":"a. femoralis profunda|a. profunda femoris","option_only":true},"canalis adductorius":{"title":"Canalis adductorius (kanaal van Hunter)","short":"Het kanaal van Hunter is een spleet aan de binnenkant van het bovenbeen waardoor de a. en v. femoralis en de n. saphenus lopen.","definition":"<p>Het <strong>canalis adductorius</strong> ligt tussen de m. vastus medialis, de adductoren en de m. sartorius. Aan het eind gaan de vaten door de hiatus adductorius naar de knieholte, waar ze vasa poplitea heten.</p>","image_url":"","wiki_title":"Adductor canal","match":"canalis adductorius|kanaal van hunter","option_only":true},"foramen obturatum":{"title":"Foramen obturatum","short":"Het foramen obturatum is de grote opening in het heupbeen, grotendeels afgesloten door een membraan, met bovenin het kanaal voor de n. en vasa obturatoria.","definition":"<p>Door het <strong>canalis obturatorius</strong> loopt de n. obturatorius naar de adductoren. Een zeldzame hernia obturatoria (vooral bij magere oudere vrouwen) kan een darmafsluiting en pijn aan de binnenkant van de dij geven (teken van Howship-Romberg).</p>","image_url":"","wiki_title":"Obturator foramen","match":"foramen obturatum","option_only":true},"kanaal van guyon":{"title":"Kanaal van Guyon","short":"Het kanaal van Guyon is een tunnel aan de pinkzijde van de pols, tussen os pisiforme en hamulus, waardoor de n. en a. ulnaris lopen.","definition":"<p>Beknelling van de n. ulnaris in het <strong>kanaal van Guyon</strong> (bijv. bij fietsers of door een ganglion) geeft zwakte van de intrinsieke handspieren en eventueel gevoelsstoornis van de pink, terwijl de rug van de hand aan de pinkzijde gespaard blijft.</p>","image_url":"","wiki_title":"Ulnar canal","match":"kanaal van guyon|loge de guyon","option_only":true},"kyphose":{"title":"Kyfose","short":"Kyfose is de naar achteren bolle kromming van de wervelkolom; normaal in de borstwervelkolom, bij overmaat een bolle rug.","definition":"<p>Een <strong>hyperkyfose</strong> ontstaat o.a. door de ziekte van Scheuermann (jongeren, wigvormige wervels), osteoporotische wervelinzakkingen, de ziekte van Bechterew of een slechte houding.</p>","image_url":"","wiki_title":"Kyphosis","match":"kyphose|kyfose|hyperkyfose","option_only":true},"scoliose":{"title":"Scoliose","short":"Scoliose is een zijwaartse verkromming van de wervelkolom met rotatie van de wervels.","definition":"<p>De meest voorkomende vorm is de <strong>idiopathische adolescentenscoliose</strong>, vaker bij meisjes. Bij de buktest (Adams) is een ribbenbult zichtbaar. Behandeling afhankelijk van de hoek en de resterende groei: observatie, een brace of een operatie. Scoliose kan ook secundair zijn aan neuromusculaire ziekten of een beenlengteverschil.</p>","image_url":"","wiki_title":"Scoliosis","match":"scoliose","option_only":true},"foramen intervertebrale":{"title":"Foramen intervertebrale","short":"Het foramen intervertebrale is de opening tussen twee wervels waardoor de spinale zenuw het wervelkanaal verlaat.","definition":"<p>Een vernauwing van het <strong>foramen intervertebrale</strong> door een hernia, osteofyten of degeneratie kan een zenuwwortel beknellen (radiculopathie).</p>","image_url":"","wiki_title":"Intervertebral foramen","match":"foramen intervertebrale|foramina intervertebralia","option_only":true},"foramen transversarium":{"title":"Foramen transversarium","short":"De foramina transversaria zijn openingen in de dwarsuitsteeksels van de halswervels waardoor de a. vertebralis loopt.","definition":"<p>De a. vertebralis loopt meestal vanaf C6 omhoog door de <strong>foramina transversaria</strong> en gaat via het foramen magnum de schedel in. C7 heeft een foramen waar meestal alleen venen door lopen.</p>","image_url":"","wiki_title":"Transverse foramen","match":"foramen transversarium|foramina transversaria","option_only":true},"os ischium":{"title":"Os ischii (zitbeen)","short":"Het os ischii is het onderste-achterste deel van het heupbeen, met de zitknobbel (tuber ischiadicum).","definition":"<p>Aan het <strong>tuber ischiadicum</strong> hechten de hamstrings aan; bij jonge sporters kan hier een avulsiefractuur ontstaan. Bij zitten draagt het tuber het lichaamsgewicht.</p>","image_url":"","wiki_title":"Ischium","match":"os ischium|os ischii|zitbeen|tuber ischiadicum","option_only":true},"malleolus medialis":{"title":"Malleolus medialis en lateralis","short":"De malleolus medialis (binnenenkel) hoort bij de tibia, de malleolus lateralis (buitenenkel) bij de fibula; samen vormen ze de enkelvork.","definition":"<p>De <strong>malleolus lateralis</strong> reikt verder naar beneden dan de medialis. Volgens de Ottawa-enkelregels is een röntgenfoto nodig bij drukpijn op de achterrand of punt van een malleolus of als de patiënt niet kan lopen.</p>","image_url":"","wiki_title":"Malleolus","match":"malleolus medialis|malleolus lateralis|laterale malleolus|mediale malleolus|enkelknobbel","option_only":true},"tuberositas tibiae":{"title":"Tuberositas tibiae","short":"De tuberositas tibiae is de knobbel aan de voorzijde van de tibia waar de patellapees aanhecht.","definition":"<p>Bij sportende adolescenten kan de groeikern van de <strong>tuberositas tibiae</strong> geïrriteerd raken door trekkracht van de patellapees (ziekte van Osgood-Schlatter).</p>","image_url":"","wiki_title":"Tibial tuberosity","match":"tuberositas tibiae","option_only":true},"predikers hand":{"title":"Predikershand","short":"De predikershand ontstaat bij een hoog letsel van de n. medianus: bij een poging een vuist te maken blijven wijs- en middelvinger gestrekt.","definition":"<p>Bij de <strong>predikershand</strong> (eedhand) vallen de lange buigspieren van duim, wijs- en middelvinger uit. Bij een laag medianusletsel (carpale tunnel) staan vooral gevoelsstoornis en zwakte van de duimmuis op de voorgrond.</p>","image_url":"","wiki_title":"Median nerve palsy","match":"predikers hand|predikershand|eedhand","option_only":true},"lactaat":{"title":"Lactaat","short":"Lactaat ontstaat uit pyruvaat bij anaerobe glycolyse; een verhoogd lactaat in het bloed wijst vaak op weefselhypoxie.","definition":"<p>Bij onvoldoende zuurstof zet lactaatdehydrogenase pyruvaat om in <strong>lactaat</strong> om NAD⁺ te regenereren. De lever kan lactaat weer omzetten in glucose (Cori-cyclus). Een verhoogd lactaat bij shock of sepsis is een maat voor de ernst; ook leverfalen, metformine en intoxicaties kunnen het verhogen.</p>","image_url":"","wiki_title":"Lactic acid","match":"lactaat|melkzuur","option_only":true},"plurivacuolair vetweefsel":{"title":"Bruin vetweefsel","short":"Bruin vetweefsel bevat veel kleine vetdruppels en mitochondriën met UCP1 en dient om warmte te maken.","definition":"<p><strong>Bruin vet</strong> ontkoppelt de ademhalingsketen via thermogenine (UCP1), zodat energie als warmte vrijkomt. Pasgeborenen hebben er veel van (tussen de schouderbladen, rond de nieren), omdat ze nog niet kunnen rillen. Het wordt geactiveerd door kou via noradrenaline (β3-receptoren).</p>","image_url":"","wiki_title":"Brown adipose tissue","match":"plurivacuolair vetweefsel","option_only":true},"anf":{"title":"Antinucleaire antistoffen (ANA)","short":"Antinucleaire antistoffen zijn auto-antistoffen tegen kerncomponenten; een positieve ANA past bij SLE en andere bindweefselziekten, maar is weinig specifiek.","definition":"<p>De <strong>ANA</strong> wordt bepaald met immunofluorescentie. Ze is bijna altijd positief bij SLE (gevoelig), maar ook bij Sjögren, systemische sclerose, geneesmiddel-lupus en bij een deel van de gezonde mensen (vooral ouderen). Daarom wordt bij een positieve ANA verder gekeken naar specifieke antistoffen (dsDNA, Sm, SSA, SSB, Scl-70).</p>","image_url":"","wiki_title":"Antinuclear antibody","match":"anf","option_only":true},"de achillespees":{"title":"Achillespees","short":"De achillespees is de sterkste pees van het lichaam; ze verbindt de kuitspieren met de calcaneus.","definition":"<p>Een <strong>achillespeesruptuur</strong> ontstaat vaak bij explosieve bewegingen bij mannen van middelbare leeftijd, soms door fluorochinolonen of corticosteroïden. Er is een knal, een palpabele delle en een positieve test van Thompson (geen plantairflexie bij knijpen in de kuit). Tendinopathie geeft pijn en zwelling enkele centimeters boven de aanhechting.</p>","image_url":"","wiki_title":"Achilles tendon","match":"de achillespees","option_only":true},"ellipsoidgewricht":{"title":"Ellipsoïd gewricht","short":"Een ellipsoïd gewricht (eigewricht) is een tweeassig gewricht met een ovale kop in een ovale kom, zoals het radiocarpale gewricht.","definition":"<p>Bij een <strong>ellipsoïd gewricht</strong> (articulatio ellipsoidea) past een eivormige, bolle gewrichtskop in een ovale kom. Er is beweging mogelijk om twee assen (flexie/extensie en abductie/adductie), maar geen echte rotatie. Voorbeelden zijn het radiocarpale (pols)gewricht en het atlanto-occipitale gewricht.</p>","image_url":"","wiki_title":"Condyloid joint","match":"ellipsoidgewricht","option_only":true},"vlakgewricht":{"title":"Vlak gewricht","short":"Een vlak gewricht heeft (vrijwel) vlakke gewrichtsvlakken die alleen kleine glijbewegingen toestaan.","definition":"<p>Bij een <strong>vlak gewricht</strong> (articulatio plana) glijden twee vrijwel vlakke gewrichtsvlakken langs elkaar. De beweeglijkheid is klein en wordt beperkt door kapsel en banden. Voorbeelden zijn de facetgewrichten van de wervelkolom, het acromioclaviculaire gewricht en gewrichten tussen de handwortelbeentjes.</p>","image_url":"","wiki_title":"Plane joint","match":"vlakgewricht","option_only":true},"fractuur van de humerus":{"title":"Humerusfractuur","short":"Een humerusfractuur is een breuk van het opperarmbeen; proximaal vooral bij ouderen, in de schacht met risico op letsel van de n. radialis.","definition":"<p><strong>Proximale humerusfracturen</strong> komen vooral bij oudere vrouwen met osteoporose voor en worden vaak conservatief behandeld. Bij een fractuur van het collum chirurgicum kan de n. axillaris beschadigd raken, bij een schachtfractuur de n. radialis (dropshand) en bij een suprachondylaire fractuur bij kinderen de a. brachialis en n. medianus.</p>","image_url":"","wiki_title":"Humerus fracture","match":"fractuur van de humerus","option_only":true},"jichtartritis":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jichtartritis","option_only":true},"infectieuze artritis":{"title":"Septische artritis","short":"Septische artritis is een bacteriële infectie van een gewricht (vaak S. aureus): acuut, pijnlijk, gezwollen, warm gewricht met koorts; een spoedgeval.","definition":"<p>Bij <strong>septische artritis</strong> raakt een gewricht geïnfecteerd, meestal via de bloedbaan, soms na een punctie of operatie. De meest voorkomende verwekker is <em>Staphylococcus aureus</em>; bij seksueel actieve jongvolwassenen ook <em>Neisseria gonorrhoeae</em>.</p><p>Het geeft een acuut rood, warm, gezwollen en zeer pijnlijk gewricht (vaak de knie) met bewegingsbeperking en meestal koorts. Diagnose door punctie (troebel synoviaal vocht met veel leukocyten, kweek). Snel draineren en antibiotica zijn nodig om kraakbeenvernietiging te voorkomen.</p>","image_url":"","wiki_title":"Septic arthritis","match":"infectieuze artritis","option_only":true},"suppuratieve artritis":{"title":"Septische artritis","short":"Septische artritis is een bacteriële infectie van een gewricht (vaak S. aureus): acuut, pijnlijk, gezwollen, warm gewricht met koorts; een spoedgeval.","definition":"<p>Bij <strong>septische artritis</strong> raakt een gewricht geïnfecteerd, meestal via de bloedbaan, soms na een punctie of operatie. De meest voorkomende verwekker is <em>Staphylococcus aureus</em>; bij seksueel actieve jongvolwassenen ook <em>Neisseria gonorrhoeae</em>.</p><p>Het geeft een acuut rood, warm, gezwollen en zeer pijnlijk gewricht (vaak de knie) met bewegingsbeperking en meestal koorts. Diagnose door punctie (troebel synoviaal vocht met veel leukocyten, kweek). Snel draineren en antibiotica zijn nodig om kraakbeenvernietiging te voorkomen.</p>","image_url":"","wiki_title":"Septic arthritis","match":"suppuratieve artritis","option_only":true},"wervelkanaalstenose":{"title":"Lumbale kanaalstenose","short":"Bij lumbale kanaalstenose is het wervelkanaal in de lage rug vernauwd, met pijn in de benen bij lopen die verbetert bij voorover buigen.","definition":"<p>Typisch voor <strong>neurogene claudicatio</strong> is dat de klachten verbeteren bij zitten of voorover buigen (fietsen gaat beter dan lopen), in tegenstelling tot vasculaire claudicatio, die bij stilstaan al verbetert. Behandeling: fysiotherapie, pijnstilling en eventueel decompressie.</p>","image_url":"","wiki_title":"Lumbar spinal stenosis","match":"wervelkanaalstenose","option_only":true},"radiale deviatie":{"title":"Ulnairdeviatie","short":"Ulnairdeviatie is het zijwaarts kantelen van de hand naar de pinkzijde in het polsgewricht.","definition":"<p><strong>Ulnairdeviatie</strong> gebeurt vooral in het radiocarpale gewricht; de tegenbeweging is radiaaldeviatie. Bij reumatoïde artritis ontstaat vaak een ulnaire deviatie van de vingers in de MCP-gewrichten.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"radiale deviatie","option_only":true},"radiaaldeviatie":{"title":"Ulnairdeviatie","short":"Ulnairdeviatie is het zijwaarts kantelen van de hand naar de pinkzijde in het polsgewricht.","definition":"<p><strong>Ulnairdeviatie</strong> gebeurt vooral in het radiocarpale gewricht; de tegenbeweging is radiaaldeviatie. Bij reumatoïde artritis ontstaat vaak een ulnaire deviatie van de vingers in de MCP-gewrichten.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"radiaaldeviatie","option_only":true},"straf bindweefsel":{"title":"Geordend straf bindweefsel","short":"Geordend straf bindweefsel bestaat uit dicht opeengepakte, parallel lopende collageenvezels en is erg trekvast in één richting.","definition":"<p>In <strong>geordend straf bindweefsel</strong> liggen collageen type I-vezels parallel, met daartussen rijen fibroblasten (tenocyten). Het weefsel is zeer sterk in de lengterichting maar weinig doorbloed, waardoor het traag herstelt. Het vormt pezen, ligamenten en aponeurosen.</p>","image_url":"","wiki_title":"Dense regular connective tissue","match":"straf bindweefsel","option_only":true},"processus uncinatus":{"title":"Processus uncinatus","short":"De processus uncinatus is een haakvormig uitsteeksel, o.a. van de pancreaskop achter de vasa mesenterica superiora en van het zeefbeen.","definition":"<p>Het <strong>processus uncinatus van de pancreas</strong> ligt achter de a. en v. mesenterica superior. Ook het zeefbeen en de halswervels (unco-vertebrale gewrichten) hebben een processus uncinatus.</p>","image_url":"","wiki_title":"Uncinate process of pancreas","match":"processus uncinatus","option_only":true},"tuberculum majus":{"title":"Tuberculum majus en minus","short":"Het tuberculum majus en minus zijn knobbels aan de humeruskop waaraan de rotatorcuffspieren aanhechten.","definition":"<p>Aan het <strong>tuberculum majus</strong> hechten de m. supraspinatus, infraspinatus en teres minor; aan het <strong>tuberculum minus</strong> de m. subscapularis. Tussen beide loopt de sulcus intertubercularis met de lange bicepspees. Een avulsiefractuur van het tuberculum majus komt voor bij schouderluxaties.</p>","image_url":"","wiki_title":"Greater tubercle","match":"tuberculum majus|tuberculum minus","option_only":true},"humerusschacht":{"title":"Humerusschacht","short":"De schacht van de humerus; bij een fractuur hiervan kan de n. radialis beschadigd raken.","definition":"<p>De n. radialis loopt in een groeve spiraalsgewijs om de achterkant van de <strong>humerusschacht</strong>. Bij een schachtfractuur ontstaat daardoor soms een dropshand. De meeste schachtfracturen genezen goed met een brace.</p>","image_url":"","wiki_title":"Humerus","match":"humerusschacht|humerusschachtfractuur","option_only":true},"collum chirurgicum":{"title":"Collum chirurgicum (humerus)","short":"Het collum chirurgicum is de vernauwing net onder de humeruskop; een veelvoorkomende plaats voor fracturen bij ouderen.","definition":"<p>Rond het <strong>collum chirurgicum</strong> lopen de n. axillaris en de a. circumflexa humeri posterior. Bij een fractuur hier moet het gevoel op de buitenkant van de schouder (n. axillaris) worden gecontroleerd.</p>","image_url":"","wiki_title":"Surgical neck of the humerus","match":"collum chirurgicum","option_only":true},"fysiotherapeut":{"title":"Fysiotherapeut","short":"Een fysiotherapeut behandelt klachten van het bewegingsapparaat en helpt mensen beter te bewegen, met oefentherapie, advies en manuele technieken.","definition":"<p><strong>Fysiotherapie</strong> wordt o.a. ingezet bij rug- en nekklachten, na operaties en blessures, bij artrose, COPD en na een beroerte. Het is direct toegankelijk, zonder verwijzing van de huisarts.</p>","image_url":"","wiki_title":"Physical therapy","match":"fysiotherapeut|fysiotherapie","option_only":true},"corpus vertebrae":{"title":"Wervellichaam","short":"Het corpus vertebrae is het dragende, cilindervormige voorste deel van een wervel.","definition":"<p>Het <strong>wervellichaam</strong> draagt het grootste deel van de belasting en bestaat vooral uit spongieus bot met rood beenmerg; daardoor is het een plaats voor osteoporotische inzakkingen en metastasen. Aan de achterkant vormen de pediculi en laminae de wervelboog.</p>","image_url":"","wiki_title":"Vertebra","match":"corpus vertebrae|wervellichaam","option_only":true},"pediculus arcus vertebrae":{"title":"Pediculus (wervelboogvoet)","short":"De pediculus verbindt het wervellichaam met de wervelboog en begrenst het foramen intervertebrale.","definition":"<p>De <strong>pediculi</strong> worden bij spondylodese gebruikt om pedikelschroeven in te plaatsen. Op een röntgenfoto kan het verdwijnen van een pediculus (‘winking owl sign’) op een metastase wijzen. In de lendenwervels heet het dwarsuitsteeksel processus costalis.</p>","image_url":"","wiki_title":"Vertebral pedicle","match":"pediculus arcus vertebrae|pediculus|processus costalis","option_only":true},"nucleïnezuur":{"title":"Nucleïnezuren","short":"Nucleïnezuren (DNA en RNA) zijn ketens van nucleotiden die erfelijke informatie opslaan en overbrengen.","definition":"<p>Een nucleotide bestaat uit een suiker (deoxyribose of ribose), een fosfaatgroep en een base (A, G, C en T of U). DNA is dubbelstrengs met basenparing A-T en G-C; RNA is meestal enkelstrengs en gebruikt uracil in plaats van thymine.</p>","image_url":"","wiki_title":"Nucleic acid","match":"nucleïnezuur|nucleïnezuren","option_only":true},"osteoblasten":{"title":"Osteoblasten","short":"Osteoblasten zijn de botvormende cellen die osteoïd maken en de mineralisatie regelen.","definition":"<p><strong>Osteoblasten</strong> ontstaan uit mesenchymale cellen (via RUNX2) en maken collageen type I, alkalisch fosfatase en osteocalcine. Ze sturen via RANKL ook de osteoclasten aan. Ingemetselde osteoblasten worden osteocyten.</p>","image_url":"","wiki_title":"Osteoblast","match":"osteoblasten|osteoblast","option_only":true},"clavicula fractuur":{"title":"Claviculafractuur","short":"Een claviculafractuur is een breuk van het sleutelbeen, meestal in het middelste derde na een val op de schouder.","definition":"<p><strong>Claviculafracturen</strong> komen veel voor bij kinderen en jongvolwassenen. Het mediale fragment wordt door de m. sternocleidomastoideus omhoog getrokken. De meeste genezen goed met een mitella; bij grote verplaatsing of verkorting kan operatie nodig zijn. Zelden raken de onderliggende vaten of plexus brachialis beschadigd.</p>","image_url":"","wiki_title":"Clavicle fracture","match":"clavicula fractuur","option_only":true},"hyperuricemie":{"title":"Urinezuur","short":"Urinezuur is het eindproduct van de purineafbraak; een te hoge spiegel kan leiden tot jicht en nierstenen.","definition":"<p><strong>Urinezuur</strong> wordt gevormd door xanthineoxidase en vooral via de nier uitgescheiden. Hyperurikemie ontstaat door verminderde uitscheiding (nierfunctiestoornis, diuretica, alcohol) of verhoogde aanmaak (celafbraak bij chemotherapie, purinerijk voedsel). Uraatkristallen veroorzaken jicht; allopurinol remt de vorming van urinezuur.</p>","image_url":"","wiki_title":"Uric acid","match":"hyperuricemie","option_only":true},"iliaca externa":{"title":"A. iliaca externa","short":"De a. iliaca externa loopt van de splitsing van de a. iliaca communis naar het lig. inguinale, waar ze a. femoralis gaat heten.","definition":"<p>De <strong>a. iliaca externa</strong> loopt langs de m. psoas en geeft vlak boven het lig. inguinale de a. epigastrica inferior en de a. circumflexa ilium profunda af. Bij een niertransplantatie wordt de donornier vaak op deze arterie aangesloten.</p>","image_url":"","wiki_title":"External iliac artery","match":"iliaca externa","option_only":true},"anterieure schouderdislocatie":{"title":"Schouderluxatie","short":"Bij een schouderluxatie schiet de humeruskop uit de kom, meestal naar voren-onder.","definition":"<p>Bij een <strong>anterieure schouderluxatie</strong> (verreweg het meest voorkomend) staat de arm in lichte abductie en exorotatie, met een afgeplatte schouderronding en een leeg gevoel onder het acromion. Controleer altijd de n. axillaris (gevoel op de schouder). Bij jongeren is recidief luxeren vaak; bij ouderen komen cuffscheuren voor. Posterieure luxaties komen voor bij epileptische aanvallen en elektrocutie.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"anterieure schouderdislocatie","option_only":true},"een anterieure schouderluxatie":{"title":"Schouderluxatie","short":"Bij een schouderluxatie schiet de humeruskop uit de kom, meestal naar voren-onder.","definition":"<p>Bij een <strong>anterieure schouderluxatie</strong> (verreweg het meest voorkomend) staat de arm in lichte abductie en exorotatie, met een afgeplatte schouderronding en een leeg gevoel onder het acromion. Controleer altijd de n. axillaris (gevoel op de schouder). Bij jongeren is recidief luxeren vaak; bij ouderen komen cuffscheuren voor. Posterieure luxaties komen voor bij epileptische aanvallen en elektrocutie.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"een anterieure schouderluxatie","option_only":true},"anterieure glenohumerale luxatie":{"title":"Schouderluxatie","short":"Bij een schouderluxatie schiet de humeruskop uit de kom, meestal naar voren-onder.","definition":"<p>Bij een <strong>anterieure schouderluxatie</strong> (verreweg het meest voorkomend) staat de arm in lichte abductie en exorotatie, met een afgeplatte schouderronding en een leeg gevoel onder het acromion. Controleer altijd de n. axillaris (gevoel op de schouder). Bij jongeren is recidief luxeren vaak; bij ouderen komen cuffscheuren voor. Posterieure luxaties komen voor bij epileptische aanvallen en elektrocutie.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"anterieure glenohumerale luxatie","option_only":true},"humerus fractuur":{"title":"Humerusfractuur","short":"Een humerusfractuur is een breuk van het opperarmbeen; proximaal vooral bij ouderen, in de schacht met risico op letsel van de n. radialis.","definition":"<p><strong>Proximale humerusfracturen</strong> komen vooral bij oudere vrouwen met osteoporose voor en worden vaak conservatief behandeld. Bij een fractuur van het collum chirurgicum kan de n. axillaris beschadigd raken, bij een schachtfractuur de n. radialis (dropshand) en bij een suprachondylaire fractuur bij kinderen de a. brachialis en n. medianus.</p>","image_url":"","wiki_title":"Humerus fracture","match":"humerus fractuur","option_only":true},"subcapitale humerusfractuur":{"title":"Humerusfractuur","short":"Een humerusfractuur is een breuk van het opperarmbeen; proximaal vooral bij ouderen, in de schacht met risico op letsel van de n. radialis.","definition":"<p><strong>Proximale humerusfracturen</strong> komen vooral bij oudere vrouwen met osteoporose voor en worden vaak conservatief behandeld. Bij een fractuur van het collum chirurgicum kan de n. axillaris beschadigd raken, bij een schachtfractuur de n. radialis (dropshand) en bij een suprachondylaire fractuur bij kinderen de a. brachialis en n. medianus.</p>","image_url":"","wiki_title":"Humerus fracture","match":"subcapitale humerusfractuur","option_only":true},"elleboog luxatie":{"title":"Elleboogluxatie","short":"Bij een elleboogluxatie schieten ulna en radius uit het gewricht met de humerus, meestal naar achteren.","definition":"<p>Een <strong>posterieure elleboogluxatie</strong> ontstaat bij een val op de uitgestrekte arm. Controleer altijd de doorbloeding (a. brachialis) en de zenuwen (n. ulnaris, n. medianus). Bij jonge kinderen komt vooral de ‘zondagsarmpje’-subluxatie van de radiuskop voor, door trekken aan de gestrekte arm.</p>","image_url":"","wiki_title":"Elbow dislocation","match":"elleboog luxatie","option_only":true},"luxatie van het ellebooggewricht":{"title":"Elleboogluxatie","short":"Bij een elleboogluxatie schieten ulna en radius uit het gewricht met de humerus, meestal naar achteren.","definition":"<p>Een <strong>posterieure elleboogluxatie</strong> ontstaat bij een val op de uitgestrekte arm. Controleer altijd de doorbloeding (a. brachialis) en de zenuwen (n. ulnaris, n. medianus). Bij jonge kinderen komt vooral de ‘zondagsarmpje’-subluxatie van de radiuskop voor, door trekken aan de gestrekte arm.</p>","image_url":"","wiki_title":"Elbow dislocation","match":"luxatie van het ellebooggewricht","option_only":true},"lig. talofibulare posterior (tfp)":{"title":"Ligamentum talofibulare posterius","short":"Het ligamentum talofibulare posterius is de sterkste laterale enkelband, van de malleolus lateralis naar de achterzijde van de talus.","definition":"<p>Het <strong>lig. talofibulare posterius</strong> loopt vrijwel horizontaal en raakt bij een gewoon inversietrauma zelden beschadigd; dat gebeurt pas bij ernstige letsels zoals een enkelluxatie.</p>","image_url":"","wiki_title":"Posterior talofibular ligament","match":"lig. talofibulare posterior (tfp)","option_only":true},"lig. talofibulare posterior":{"title":"Ligamentum talofibulare posterius","short":"Het ligamentum talofibulare posterius is de sterkste laterale enkelband, van de malleolus lateralis naar de achterzijde van de talus.","definition":"<p>Het <strong>lig. talofibulare posterius</strong> loopt vrijwel horizontaal en raakt bij een gewoon inversietrauma zelden beschadigd; dat gebeurt pas bij ernstige letsels zoals een enkelluxatie.</p>","image_url":"","wiki_title":"Posterior talofibular ligament","match":"lig. talofibulare posterior","option_only":true},"lig. calcaneofibulare (cf)":{"title":"Ligamentum calcaneofibulare","short":"Het ligamentum calcaneofibulare is een laterale enkelband van de malleolus lateralis naar de calcaneus.","definition":"<p>Het <strong>lig. calcaneofibulare</strong> vormt met het lig. talofibulare anterius en posterius het laterale bandcomplex van de enkel en overspant zowel het bovenste als het onderste spronggewricht.</p>","image_url":"","wiki_title":"Calcaneofibular ligament","match":"lig. calcaneofibulare (cf)","option_only":true},"lig. deltoïdeum":{"title":"Ligamentum deltoideum","short":"Het ligamentum deltoideum is de sterke, waaiervormige band aan de binnenzijde van de enkel.","definition":"<p>Het <strong>lig. deltoideum</strong> loopt van de malleolus medialis naar os naviculare, talus en calcaneus en heeft een oppervlakkige en een diepe laag. Het is veel sterker dan de laterale enkelbanden en stabiliseert de enkel aan de mediale zijde.</p>","image_url":"","wiki_title":"Deltoid ligament","match":"lig. deltoïdeum","option_only":true},"vasculaire claudicatio intermittens":{"title":"Claudicatio intermittens","short":"Claudicatio intermittens is pijn in de kuit of bil bij lopen die bij stilstaan verdwijnt, door perifeer arterieel vaatlijden.","definition":"<p>Bij <strong>claudicatio</strong> zijn de beenarteriën vernauwd door atherosclerose. De enkel-armindex is verlaagd (&lt;0,9). Behandeling: stoppen met roken, gesuperviseerde looptraining, een plaatjesremmer en statine; bij ernstige klachten of kritieke ischemie (rustpijn, wonden) revascularisatie.</p>","image_url":"","wiki_title":"Intermittent claudication","match":"vasculaire claudicatio intermittens","option_only":true},"collumfractuur":{"title":"Femurfractuur","short":"Een femurfractuur is een breuk van het dijbeen; bij ouderen vooral in het collum (heupfractuur), bij jongeren vaak in de schacht door hoog geweld.","definition":"<p><strong>Heupfracturen</strong> bij ouderen (mediale collumfractuur of pertrochantere fractuur) ontstaan vaak na een val bij osteoporose; het been staat verkort en naar buiten gedraaid. Ze hebben een hoge sterfte en morbiditeit. Schachtfracturen kunnen veel bloedverlies geven. Behandeling is meestal operatief.</p>","image_url":"","wiki_title":"Femoral fracture","match":"collumfractuur","option_only":true},"collumfractuur links":{"title":"Femurfractuur","short":"Een femurfractuur is een breuk van het dijbeen; bij ouderen vooral in het collum (heupfractuur), bij jongeren vaak in de schacht door hoog geweld.","definition":"<p><strong>Heupfracturen</strong> bij ouderen (mediale collumfractuur of pertrochantere fractuur) ontstaan vaak na een val bij osteoporose; het been staat verkort en naar buiten gedraaid. Ze hebben een hoge sterfte en morbiditeit. Schachtfracturen kunnen veel bloedverlies geven. Behandeling is meestal operatief.</p>","image_url":"","wiki_title":"Femoral fracture","match":"collumfractuur links","option_only":true},"mediale collumfractuur":{"title":"Femurfractuur","short":"Een femurfractuur is een breuk van het dijbeen; bij ouderen vooral in het collum (heupfractuur), bij jongeren vaak in de schacht door hoog geweld.","definition":"<p><strong>Heupfracturen</strong> bij ouderen (mediale collumfractuur of pertrochantere fractuur) ontstaan vaak na een val bij osteoporose; het been staat verkort en naar buiten gedraaid. Ze hebben een hoge sterfte en morbiditeit. Schachtfracturen kunnen veel bloedverlies geven. Behandeling is meestal operatief.</p>","image_url":"","wiki_title":"Femoral fracture","match":"mediale collumfractuur","option_only":true},"pertrochantere fractuur":{"title":"Femurfractuur","short":"Een femurfractuur is een breuk van het dijbeen; bij ouderen vooral in het collum (heupfractuur), bij jongeren vaak in de schacht door hoog geweld.","definition":"<p><strong>Heupfracturen</strong> bij ouderen (mediale collumfractuur of pertrochantere fractuur) ontstaan vaak na een val bij osteoporose; het been staat verkort en naar buiten gedraaid. Ze hebben een hoge sterfte en morbiditeit. Schachtfracturen kunnen veel bloedverlies geven. Behandeling is meestal operatief.</p>","image_url":"","wiki_title":"Femoral fracture","match":"pertrochantere fractuur","option_only":true},"proximale femurfractuur":{"title":"Femurfractuur","short":"Een femurfractuur is een breuk van het dijbeen; bij ouderen vooral in het collum (heupfractuur), bij jongeren vaak in de schacht door hoog geweld.","definition":"<p><strong>Heupfracturen</strong> bij ouderen (mediale collumfractuur of pertrochantere fractuur) ontstaan vaak na een val bij osteoporose; het been staat verkort en naar buiten gedraaid. Ze hebben een hoge sterfte en morbiditeit. Schachtfracturen kunnen veel bloedverlies geven. Behandeling is meestal operatief.</p>","image_url":"","wiki_title":"Femoral fracture","match":"proximale femurfractuur","option_only":true},"acute osteomyelitis":{"title":"Osteomyelitis","short":"Osteomyelitis is een infectie van het bot, meestal door Staphylococcus aureus.","definition":"<p><strong>Osteomyelitis</strong> ontstaat via de bloedbaan (vooral bij kinderen in de metafysen van lange pijpbeenderen), vanuit een nabijgelegen infectie (bijv. diabetische voet, decubitus) of na een open fractuur of operatie. Klachten: pijn, koorts, zwelling. Diagnose met MRI en kweek (bot of bloed). Chronische osteomyelitis met dood bot (sequester) vergt vaak chirurgie naast langdurige antibiotica.</p>","image_url":"","wiki_title":"Osteomyelitis","match":"acute osteomyelitis","option_only":true},"oog":{"title":"Het oor","short":"Het oor bestaat uit buiten-, midden- en binnenoor en verzorgt het gehoor en het evenwicht.","definition":"<p>Het <strong>oor</strong> is opgebouwd uit drie delen. Het <em>buitenoor</em> (oorschelp en gehoorgang) vangt geluid op; het <em>middenoor</em> (trommelvlies en gehoorbeentjes hamer, aambeeld en stijgbeugel) versterkt de trillingen; het <em>binnenoor</em> zet ze om in zenuwsignalen.</p><p>Het binnenoor bevat het slakkenhuis (cochlea) voor het gehoor en het vestibulaire systeem (halfcirkelvormige kanalen, utriculus en sacculus) voor evenwicht. Signalen lopen via de n. vestibulocochlearis (VIII) naar de hersenstam.</p>","image_url":"","wiki_title":"Ear","match":"oog","option_only":true},"ligamentum talofibulare anterius":{"title":"Lig. talofibulare anterius","short":"Het lig. talofibulare anterius loopt van de laterale malleolus naar de talus en is de enkelband die het vaakst scheurt.","definition":"<p>Het <strong>lig. talofibulare anterius</strong> is vooral gespannen in plantairflexie, de stand waarin inversietrauma's meestal optreden. Een positieve voorste schuiflade wijst op een ruptuur.</p>","image_url":"","wiki_title":"Anterior talofibular ligament","match":"ligamentum talofibulare anterius|ligamentum fibulotalare anterius|lig. talofibulare anterior (tfa)|lig. talofibulare anterior|atfl","option_only":true},"mri scan":{"title":"MRI","short":"MRI maakt met een sterk magneetveld en radiogolven gedetailleerde beelden van weke delen, zonder ioniserende straling.","definition":"<p>Bij <strong>MRI</strong> worden waterstofkernen in een sterk magneetveld door radiogolven aangeslagen; het signaal bij terugkeer verschilt per weefseltype. MRI is bijzonder geschikt voor hersenen, ruggenmerg, gewrichten, weke delen en het bekken. Nadelen zijn de lange duur, kosten en beperkingen bij pacemakers en sommige metalen implantaten.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri scan","option_only":true},"n. fibularis profundus":{"title":"N. fibularis profundus","short":"Tak van de n. fibularis communis die de spieren aan de voorzijde van het onderbeen innerveert.","definition":"<p>De <b>n. fibularis profundus</b> ontstaat bij het collum fibulae uit de n. fibularis communis en loopt in de voorste loge van het onderbeen. Hij innerveert de m. tibialis anterior, m. extensor hallucis longus en m. extensor digitorum longus (dorsaalflexie van voet en tenen) en heeft een klein sensibel gebied op de voetrug.</p>","image_url":"","wiki_title":"Deep peroneal nerve","match":"n. fibularis profundus","option_only":true},"vetzuurverbranding":{"title":"Vetzuren","short":"Vetzuren zijn koolstofketens met een carboxylgroep; ze worden via bèta-oxidatie in de mitochondriën verbrand en leveren veel ATP, maar alleen aeroob.","definition":"<p><strong>Vetzuren</strong> zijn lange koolwaterstofketens met een carboxylgroep, verzadigd of onverzadigd. Ze worden opgeslagen als triglyceriden in vetweefsel en bij behoefte door lipolyse vrijgemaakt.</p><p>In de cel worden ze met carnitine de mitochondriën in getransporteerd en via <em>bèta-oxidatie</em> afgebroken tot acetyl-CoA, dat de citroenzuurcyclus in gaat. Vetzuren leveren per gram veel meer energie dan glucose, maar alleen via zuurstofafhankelijke stofwisseling en relatief langzaam. In de lever kunnen ze ketonlichamen vormen.</p>","image_url":"","wiki_title":"Fatty acid","match":"vetzuurverbranding","option_only":true},"hartspierweefsel":{"title":"Hartspierweefsel","short":"Dwarsgestreept, onwillekeurig spierweefsel met vertakte cellen en glansstrepen (intercalated discs); regenereert nauwelijks.","definition":"<p><b>Hartspierweefsel</b> (myocard) bestaat uit vertakte, gestreepte cellen verbonden door glansstrepen met gap junctions. Het is onwillekeurig en kan zich vrijwel niet herstellen door het ontbreken van satellietcellen.</p>","image_url":"","wiki_title":"Cardiac muscle","match":"hartspierweefsel","option_only":true},"calcitonine":{"title":"Calcitonine","short":"Hormoon uit de parafolliculaire C-cellen van de schildklier.","definition":"<p><strong>Calcitonine</strong> wordt gemaakt door de parafolliculaire C-cellen van de schildklier als reactie op een stijging van het calcium. Het remt osteoclasten. Bij de mens is de fysiologische rol beperkt: na een totale thyreoïdectomie blijft de calciumspiegel normaal. Calcitonine is een tumormarker voor het medullair schildkliercarcinoom.</p>","image_url":"","wiki_title":"Calcitonin","match":"calcitonine","option_only":true},"voetheffersparese":{"title":"Voetheffersparese","short":"Krachtsverlies van de spieren die de voet optrekken (dorsaalflexie), met een klapvoet als gevolg.","definition":"<p>Een <strong>voetheffersparese</strong> is zwakte van de dorsaalflexoren van de voet (o.a. m. tibialis anterior). De voet hangt slap naar beneden; patiënten lopen met een steppagegang om niet met de tenen te blijven haken. Oorzaken liggen in de zenuw, de zenuwwortel, de plexus of centraal.</p>","image_url":"","wiki_title":"Foot drop","match":"voetheffersparese","option_only":true},"incisura trochlearis":{"title":"Incisura trochlearis","short":"Halvemaanvormige uitholling van de ulna die om de trochlea van de humerus grijpt.","definition":"<p>De <b>incisura trochlearis</b> is de C-vormige inkeping aan de bovenzijde van de ulna (tussen olecranon en processus coronoideus) die de trochlea humeri omvat en zo het scharnier van het ellebooggewricht vormt.</p>","image_url":"","wiki_title":"Trochlear notch","match":"incisura trochlearis","option_only":true},"foramen vertebrale":{"title":"Foramen vertebrale","short":"Het foramen vertebrale is de opening in een wervel, begrensd door corpus en arcus, waardoor het ruggenmerg loopt; de opeenstapeling vormt de canalis vertebralis.","definition":"<p>Het <strong>foramen vertebrale</strong> wordt gevormd door het wervellichaam (ventraal) en de wervelboog (dorsaal). Alle foramina samen vormen het <em>wervelkanaal</em> (canalis vertebralis) dat het ruggenmerg omhult.</p>","image_url":"","wiki_title":"Vertebral foramen","match":"foramen vertebrale","option_only":true},"polyneuropathie":{"title":"Polyneuropathie","short":"Diffuse aandoening van perifere zenuwen, vaak symmetrisch distaal, met sensibiliteitsstoornissen en verlaagde reflexen.","definition":"<p><b>Polyneuropathie</b> is een diffuse aantasting van perifere zenuwen, meestal symmetrisch en distaal (sok-handschoenpatroon), met sensibiliteitsstoornissen, verlaagde reflexen en soms spierzwakte. Frequente oorzaken: diabetes en alcohol.</p>","image_url":"","wiki_title":"Polyneuropathy","match":"polyneuropathie","option_only":true},"creatine fosfaat":{"title":"Creatinefosfaat","short":"Energierijke fosfaatverbinding die zeer snel ATP kan regenereren voor kortdurende, explosieve inspanning zoals sprinten.","definition":"<p><b>Creatinefosfaat (fosfocreatine)</b> levert onmiddellijk een fosfaatgroep om ADP snel om te zetten in ATP. Dit systeem domineert bij korte, maximale inspanning (enkele seconden) zoals de 100 m sprint.</p>","image_url":"","wiki_title":"Phosphocreatine","match":"creatine fosfaat","option_only":true},"monocyten":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyten","option_only":true},"hla-b27+":{"title":"HLA-B27","short":"HLA-B27 is een MHC klasse I-variant die sterk geassocieerd is met spondyloartritiden zoals de ziekte van Bechterew.","definition":"<p>Dragers van <strong>HLA-B27</strong> hebben een sterk verhoogd risico op axiale spondyloartritis, reactieve artritis, uveïtis anterior en artritis bij IBD of psoriasis. Toch krijgt de grote meerderheid van de dragers nooit een van deze ziekten, en een deel van de patiënten is HLA-B27-negatief: de test ondersteunt de diagnose, maar bewijst haar niet.</p>","image_url":"","wiki_title":"HLA-B27","match":"hla-b27+","option_only":true},"a.carotis":{"title":"A. carotis communis","short":"De a. carotis communis loopt in de hals omhoog en splitst ter hoogte van het schildkraakbeen in de a. carotis interna en externa.","definition":"<p>Rechts komt de <strong>a. carotis communis</strong> uit de truncus brachiocephalicus, links rechtstreeks uit de aortaboog. Bij de splitsing liggen de sinus caroticus (baroreceptoren) en het glomus caroticum (chemoreceptoren). De carotispols is lateraal van het strottenhoofd voelbaar.</p>","image_url":"","wiki_title":"Common carotid artery","match":"a.carotis","option_only":true},"aanwezigheid van hla b27 antigeen":{"title":"HLA-B27","short":"HLA-B27 is een MHC klasse I-variant die sterk geassocieerd is met spondyloartritiden zoals de ziekte van Bechterew.","definition":"<p>Dragers van <strong>HLA-B27</strong> hebben een sterk verhoogd risico op axiale spondyloartritis, reactieve artritis, uveïtis anterior en artritis bij IBD of psoriasis. Toch krijgt de grote meerderheid van de dragers nooit een van deze ziekten, en een deel van de patiënten is HLA-B27-negatief: de test ondersteunt de diagnose, maar bewijst haar niet.</p>","image_url":"","wiki_title":"HLA-B27","match":"aanwezigheid van hla b27 antigeen","option_only":true},"vetzuuroxidatie":{"title":"Vetzuren","short":"Vetzuren zijn koolstofketens met een carboxylgroep; ze worden via bèta-oxidatie in de mitochondriën verbrand en leveren veel ATP, maar alleen aeroob.","definition":"<p><strong>Vetzuren</strong> zijn lange koolwaterstofketens met een carboxylgroep, verzadigd of onverzadigd. Ze worden opgeslagen als triglyceriden in vetweefsel en bij behoefte door lipolyse vrijgemaakt.</p><p>In de cel worden ze met carnitine de mitochondriën in getransporteerd en via <em>bèta-oxidatie</em> afgebroken tot acetyl-CoA, dat de citroenzuurcyclus in gaat. Vetzuren leveren per gram veel meer energie dan glucose, maar alleen via zuurstofafhankelijke stofwisseling en relatief langzaam. In de lever kunnen ze ketonlichamen vormen.</p>","image_url":"","wiki_title":"Fatty acid","match":"vetzuuroxidatie","option_only":true},"calor":{"title":"Klassieke ontstekingsverschijnselen","short":"De klassieke verschijnselen van een acute ontsteking zijn rubor (roodheid), calor (warmte), tumor (zwelling), dolor (pijn) en functio laesa (functieverlies).","definition":"<p>Roodheid en warmte komen door vaatverwijding, zwelling door toegenomen vaatdoorlaatbaarheid (oedeem), en pijn door mediatoren zoals bradykinine en prostaglandinen.</p>","image_url":"","wiki_title":"Inflammation","match":"calor|rubor|tumor|dolor|functio laesa","option_only":true}};
